import { useCallback, useEffect, useRef } from 'react';
import { AppState, AppStateStatus, Platform } from 'react-native';
import {
  navigationRef,
  userActivityTelemetryService,
} from '@mfe/core/services';

/**
 * Global zero-overhead activity & crash telemetry hook.
 *
 * Automatically tracks:
 * 1. Initial telemetry session on app mount (logOnly: true by default)
 * 2. AppState foreground/background lifecycle transitions
 * 3. Every screen navigation change via NavigationContainer callbacks
 * 4. Unhandled JS fatal errors (forwarding to the original error handler)
 */
export const useGlobalActivityTelemetry = () => {
  const lastRouteRef = useRef<string | undefined>(undefined);
  const appStateRef = useRef<AppStateStatus>(AppState.currentState);

  useEffect(() => {
    // 1. Initialize telemetry session once on mount
    userActivityTelemetryService.initSession('anonymous', `dev_${Platform.OS}`);

    // 2. Track foreground / background lifecycle changes
    const appStateSub = AppState.addEventListener('change', (nextState) => {
      if (appStateRef.current !== nextState) {
        userActivityTelemetryService.trackBreadcrumb(
          `AppState changed: ${appStateRef.current} -> ${nextState}`,
          'system',
          'system'
        );
        appStateRef.current = nextState;
      }
    });

    // 3. Global unhandled JS error capture (preserves existing handler)
    const g = globalThis as any;
    let restoreErrorHandler: (() => void) | undefined;

    if (Platform.OS === 'web' && typeof window !== 'undefined' && typeof window.addEventListener === 'function') {
      const onWindowError = (event: ErrorEvent) => {
        const err = event.error instanceof Error ? event.error : new Error(event.message || 'Unhandled Web Error');
        userActivityTelemetryService.reportCrash(err, { severity: 'FATAL' });
      };
      window.addEventListener('error', onWindowError);
      restoreErrorHandler = () => window.removeEventListener('error', onWindowError);
    } else if (g?.ErrorUtils && typeof g.ErrorUtils.getGlobalHandler === 'function') {
      const previousHandler = g.ErrorUtils.getGlobalHandler();
      g.ErrorUtils.setGlobalHandler((error: Error, isFatal?: boolean) => {
        userActivityTelemetryService.reportCrash(error, {
          severity: isFatal ? 'FATAL' : 'NON_FATAL',
        });
        if (typeof previousHandler === 'function') {
          previousHandler(error, isFatal);
        }
      });
      restoreErrorHandler = () => {
        if (previousHandler) {
          g.ErrorUtils.setGlobalHandler(previousHandler);
        }
      };
    }

    return () => {
      appStateSub.remove();
      restoreErrorHandler?.();
    };
  }, []);

  const syncCurrentRoute = useCallback(() => {
    if (!navigationRef.isReady()) return;
    const currentRoute = navigationRef.getCurrentRoute();
    const routeName = currentRoute?.name;
    if (routeName && routeName !== lastRouteRef.current) {
      lastRouteRef.current = routeName;
      userActivityTelemetryService.trackNavigation(
        routeName,
        currentRoute?.params as Record<string, unknown> | undefined
      );
    }
  }, []);

  return {
    handleNavigationReady: syncCurrentRoute,
    handleNavigationStateChange: syncCurrentRoute,
  };
};
