import React, { useState, useMemo } from 'react';
import {
  View,
  Text,
  TouchableOpacity,
  TextInput,
  ScrollView,
  StyleSheet,
  ViewStyle,
} from 'react-native';
import { useTheme } from '@mfe/core/theme/ThemeContext';
import { SearchIconSvg } from '@mfe/assets/icons/CommonIcons';
import { AppBottomSheet } from './AppBottomSheet';

export interface DropdownOption<T = string> {
  label: string;
  value: T;
  subtitle?: string;
  disabled?: boolean;
}

export interface DropdownModalProps<T = string> {
  visible: boolean;
  onClose: () => void;
  title?: string;
  options: DropdownOption<T>[];
  selectedValue?: T;
  onSelect: (value: T, option: DropdownOption<T>) => void;
  searchable?: boolean;
  searchPlaceholder?: string;
  footerNote?: string;
  maxHeightPercent?: number; // default 0.85
  style?: ViewStyle;
  testID?: string;
}

export interface DropdownSelectFieldProps<T = string> {
  label: string;
  value?: T;
  options: DropdownOption<T>[];
  onSelect: (value: T, option: DropdownOption<T>) => void;
  placeholder?: string;
  title?: string;
  searchable?: boolean;
  searchPlaceholder?: string;
  footerNote?: string;
  error?: string;
  disabled?: boolean;
  readOnly?: boolean;
  style?: ViewStyle;
  testID?: string;
}

/**
 * DropdownModal: Enterprise BottomSheet selection picker matching DBCS LOS Value Picker (M7).
 * Composes directly on the shared `AppBottomSheet` for consistent gestures, drag handles,
 * backdrop blur, and animation.
 * Features title, close button, search filter box, red highlight with checkmark (✓),
 * and optional pagination footer note.
 */
export function DropdownModal<T extends string | number = string>({
  visible,
  onClose,
  title = 'Select an option',
  options,
  selectedValue,
  onSelect,
  searchable = true,
  searchPlaceholder = 'Search',
  footerNote,
  maxHeightPercent = 0.85,
  style,
  testID = 'dropdown-modal',
}: DropdownModalProps<T>) {
  const { theme } = useTheme();
  const [searchQuery, setSearchQuery] = useState('');

  const filteredOptions = useMemo(() => {
    const q = searchQuery.trim().toLowerCase();
    if (!q) return options;
    return options.filter(
      (opt) =>
        opt.label.toLowerCase().includes(q) ||
        (opt.subtitle && opt.subtitle.toLowerCase().includes(q))
    );
  }, [options, searchQuery]);

  const handleClose = () => {
    setSearchQuery('');
    onClose();
  };

  const handleSelect = (opt: DropdownOption<T>) => {
    if (opt.disabled) return;
    onSelect(opt.value, opt);
    handleClose();
  };

  return (
    <AppBottomSheet
      visible={visible}
      onClose={handleClose}
      title={title}
      maxHeightPercent={maxHeightPercent}
      style={style}
      testID={testID}
    >
      <View style={styles.contentContainer}>
        {/* Search Bar Input */}
        {searchable ? (
          <View style={styles.searchContainer}>
            <View
              style={[
                styles.searchBox,
                {
                  backgroundColor: '#F3F4F6',
                  borderRadius: theme.radius.md,
                },
              ]}
            >
              <SearchIconSvg size={18} color="#9CA3AF" />
              <TextInput
                testID={`${testID}-search-input`}
                value={searchQuery}
                onChangeText={setSearchQuery}
                placeholder={searchPlaceholder}
                placeholderTextColor="#9CA3AF"
                style={[styles.searchInput, { color: theme.colors.text }]}
                autoCorrect={false}
                autoCapitalize="none"
                clearButtonMode="while-editing"
              />
              {searchQuery.length > 0 ? (
                <TouchableOpacity
                  testID={`${testID}-search-clear`}
                  onPress={() => setSearchQuery('')}
                  hitSlop={{ top: 8, bottom: 8, left: 8, right: 8 }}
                >
                  <Text style={styles.clearSearchText}>✕</Text>
                </TouchableOpacity>
              ) : null}
            </View>
          </View>
        ) : null}

        {/* Option List */}
        <ScrollView
          style={styles.list}
          contentContainerStyle={styles.listContent}
          keyboardShouldPersistTaps="handled"
          nestedScrollEnabled
        >
          {filteredOptions.length === 0 ? (
            <View style={styles.emptyContainer} testID={`${testID}-empty`}>
              <Text style={[styles.emptyText, { color: theme.colors.textSubtle }]}>
                No matches found
              </Text>
            </View>
          ) : (
            filteredOptions.map((opt) => {
              const isSelected = opt.value === selectedValue;
              return (
                <TouchableOpacity
                  key={String(opt.value)}
                  testID={`${testID}-item-${opt.value}`}
                  disabled={opt.disabled}
                  activeOpacity={0.7}
                  onPress={() => handleSelect(opt)}
                  style={[
                    styles.optionRow,
                    opt.disabled && styles.disabledOption,
                  ]}
                >
                  <View style={styles.optionContent}>
                    <Text
                      style={[
                        styles.optionLabel,
                        {
                          color: isSelected ? theme.colors.primary : theme.colors.text,
                          fontFamily: isSelected
                            ? theme.typography.fontFamilyBold
                            : theme.typography.fontFamily,
                          fontWeight: isSelected ? '700' : '500',
                        },
                      ]}
                    >
                      {opt.label}
                    </Text>
                    {opt.subtitle ? (
                      <Text
                        style={[
                          styles.optionSubtitle,
                          { color: theme.colors.textSubtle },
                        ]}
                      >
                        {opt.subtitle}
                      </Text>
                    ) : null}
                  </View>

                  {/* Selected Checkmark (✓) */}
                  {isSelected ? (
                    <Text
                      testID={`${testID}-checkmark-${opt.value}`}
                      style={[styles.checkmark, { color: theme.colors.primary }]}
                    >
                      ✓
                    </Text>
                  ) : null}
                </TouchableOpacity>
              );
            })
          )}

          {/* Optional Footer Note (e.g., 'List from getWard, paginated by getPickerPaging.') */}
          {footerNote ? (
            <View style={styles.footerWrap} testID={`${testID}-footer-note`}>
              <Text style={[styles.footerText, { color: theme.colors.textSubtle }]}>
                {footerNote}
              </Text>
            </View>
          ) : null}
        </ScrollView>
      </View>
    </AppBottomSheet>
  );
}

/**
 * DropdownSelectField: Form Field trigger box paired with the DropdownModal.
 * Displays field label, current value or placeholder, border states (default/focused/error),
 * and opens the BottomSheet DropdownModal upon tap.
 */
export function DropdownSelectField<T extends string | number = string>({
  label,
  value,
  options,
  onSelect,
  placeholder = 'Select an option',
  title,
  searchable = true,
  searchPlaceholder = 'Search',
  footerNote,
  error,
  disabled = false,
  readOnly = false,
  style,
  testID = 'dropdown-select-field',
}: DropdownSelectFieldProps<T>) {
  const { theme } = useTheme();
  const [modalVisible, setModalVisible] = useState(false);

  const selectedOption = options.find((o) => o.value === value);

  const handlePress = () => {
    if (disabled || readOnly) return;
    setModalVisible(true);
  };

  return (
    <View testID={testID} style={[styles.fieldContainer, style]}>
      {label ? (
        <Text style={[styles.fieldLabel, { color: theme.colors.textMuted }]}>
          {label}
        </Text>
      ) : null}

      <TouchableOpacity
        testID={`${testID}-trigger`}
        activeOpacity={disabled || readOnly ? 1 : 0.7}
        onPress={handlePress}
        style={[
          styles.fieldTriggerBox,
          {
            backgroundColor: readOnly ? '#E5E7EB' : disabled ? '#F3F4F6' : theme.colors.card,
            borderColor: error ? theme.colors.error : modalVisible ? theme.colors.primary : theme.colors.border,
            borderWidth: error || modalVisible ? 1.5 : 1,
            borderRadius: theme.radius.md,
          },
        ]}
      >
        <Text
          testID={`${testID}-display-value`}
          style={[
            styles.fieldValueText,
            {
              color: selectedOption ? theme.colors.text : '#9CA3AF',
              fontWeight: selectedOption ? '600' : '400',
            },
          ]}
          numberOfLines={1}
        >
          {selectedOption ? selectedOption.label : placeholder}
        </Text>
        {!readOnly ? (
          <Text style={[styles.fieldChevron, { color: theme.colors.textSubtle }]}>▾</Text>
        ) : null}
      </TouchableOpacity>

      {error ? (
        <Text testID={`${testID}-error`} style={[styles.fieldErrorText, { color: theme.colors.error }]}>
          {error}
        </Text>
      ) : null}

      <DropdownModal
        visible={modalVisible}
        onClose={() => setModalVisible(false)}
        title={title || label || placeholder}
        options={options}
        selectedValue={value}
        onSelect={(newVal, opt) => {
          onSelect(newVal, opt);
          setModalVisible(false);
        }}
        searchable={searchable}
        searchPlaceholder={searchPlaceholder}
        footerNote={footerNote}
        testID={`${testID}-modal`}
      />
    </View>
  );
}

