import React from 'react';
import {
  ScrollView,
  RefreshControl,
  ScrollViewProps,
  StyleSheet,
  ViewStyle,
} from 'react-native';
import { useTheme } from '@mfe/core/theme/ThemeContext';

export interface PullToRefreshScrollViewProps extends ScrollViewProps {
  /**
   * Whether the view is currently refreshing.
   */
  refreshing: boolean;
  /**
   * Async or sync callback fired when user pulls past the threshold.
   */
  onRefresh: () => void | Promise<void>;
  /**
   * Pull progress title (iOS only).
   */
  refreshTitle?: string;
  containerStyle?: ViewStyle;
  testID?: string;
}

/**
 * Universal PullToRefreshScrollView wrapping React Native's RefreshControl
 * with theme primary colors and platform-adaptive indicators.
 */
export const PullToRefreshScrollView: React.FC<PullToRefreshScrollViewProps> = ({
  refreshing,
  onRefresh,
  refreshTitle = 'Refreshing...',
  children,
  style,
  contentContainerStyle,
  testID = 'pull-to-refresh-scroll',
  ...rest
}) => {
  const { theme } = useTheme();

  return (
    <ScrollView
      testID={testID}
      style={[styles.container, style]}
      contentContainerStyle={[styles.contentContainer, contentContainerStyle]}
      refreshControl={
        <RefreshControl
          refreshing={refreshing}
          onRefresh={onRefresh}
          colors={[theme.colors.primary, '#059669', '#2563EB']} // Android rotation colors
          tintColor={theme.colors.primary} // iOS spinner tint
          title={refreshTitle}
          titleColor={theme.colors.textSecondary || '#6B7280'}
          testID={`${testID}-control`}
        />
      }
      {...rest}
    >
      {children}
    </ScrollView>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
  },
  contentContainer: {
    flexGrow: 1,
  },
});

