import React from 'react';
import {
  View,
  Text,
  StyleSheet,
  ViewStyle,
  StyleProp,
} from 'react-native';
import Svg, { Path, Circle } from 'react-native-svg';
import { AppButton } from '../button/AppButton';

export interface NoDataStateProps {
  /**
   * Title text (default: 'No data available.')
   */
  title?: string;
  /**
   * Optional descriptive message below title
   */
  message?: string;
  /**
   * Optional custom illustration or icon node
   */
  icon?: React.ReactNode;
  /**
   * Optional action button text
   */
  actionTitle?: string;
  /**
   * Optional action callback
   */
  onAction?: () => void;
  style?: StyleProp<ViewStyle>;
  testID?: string;
}

export const NoDataState: React.FC<NoDataStateProps> = ({
  title = 'No data available.',
  message,
  icon,
  actionTitle,
  onAction,
  style,
  testID = 'no-data-state',
}) => {
  return (
    <View testID={testID} style={[styles.container, style]}>
      {/* Default illustration: Enterprise Magnifying Glass inspecting Archive Box */}
      {icon ? (
        icon
      ) : (
        <View style={styles.illustrationWrap}>
          <Svg width={140} height={140} viewBox="0 0 100 100" fill="none">
            <Path d="M20 50L45 42L75 50L50 60L20 50Z" fill="#E2E8F0" />
            <Path d="M20 50V75L50 85V60L20 50Z" fill="#CBD5E1" />
            <Path d="M75 50V75L50 85V60L75 50Z" fill="#94A3B8" />
            {/* Magnifying Glass */}
            <Circle cx="55" cy="45" r="14" stroke="#475569" strokeWidth={5} fill="none" />
            <Path d="M65 55L78 68" stroke="#334155" strokeWidth={6} strokeLinecap="round" />
          </Svg>
        </View>
      )}

      <Text style={styles.titleText}>{title}</Text>

      {message ? <Text style={styles.messageText}>{message}</Text> : null}

      {actionTitle && onAction ? (
        <View style={styles.actionWrapper}>
          <AppButton
            title={actionTitle}
            variant="outline"
            size="small"
            onPress={onAction}
            testID={`${testID}-action-btn`}
          />
        </View>
      ) : null}
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    alignItems: 'center',
    justifyContent: 'center',
    paddingVertical: 40,
    paddingHorizontal: 20,
  },
  illustrationWrap: {
    alignItems: 'center',
    justifyContent: 'center',
    marginBottom: 12,
  },
  titleText: {
    fontSize: 15,
    fontWeight: '600',
    color: '#94A3B8',
    textAlign: 'center',
  },
  messageText: {
    fontSize: 13,
    color: '#64748B',
    textAlign: 'center',
    marginTop: 6,
    maxWidth: 260,
  },
  actionWrapper: {
    marginTop: 16,
  },
});

