import React, { useEffect, useState } from 'react';
import {
  View,
  Text,
  ScrollView,
  TouchableOpacity,
  StyleSheet,
  Dimensions,
  Platform,
} from 'react-native';
import { DialogUtil, ModalState } from './DialogUtil';
import { AppAlertModal } from './AppAlertModal';
import { ConfirmDialog } from './ConfirmDialog';
import { AppBottomSheet } from './AppBottomSheet';
import { ImageConfirmModal } from './ImageConfirmModal';
import { AnotherDeviceLoginConfirmModal } from './AnotherDeviceLoginConfirmModal';
import { useTheme } from '@mfe/theme';

export const GlobalModalHost: React.FC = () => {
  const [modalState, setModalState] = useState<ModalState>(DialogUtil.getState());
  const { theme } = useTheme();

  useEffect(() => {
    return DialogUtil.subscribe((newState) => {
      setModalState(newState);
    });
  }, []);

  if (!modalState.isOpen) {
    return null;
  }

  // 1. Alert Modal (with scrollable message content)
  if (modalState.modalType === 'alert') {
    const { options, resolve } = modalState;
    const {
      title = 'Notice',
      message,
      type = 'info',
      buttonText = 'OK',
      dismissible = true,
      maxWidth = 420,
      testID = 'global-alert-modal',
      content,
    } = options;

    const screenHeight = Dimensions.get('window').height;
    const maxContentHeight = Math.min(screenHeight * 0.55, 380);

    const isCodeOrJson =
      message &&
      (message.startsWith('{') ||
        message.startsWith('[') ||
        message.includes('\n') ||
        message.length > 80);

    return (
      <AppAlertModal
        visible={true}
        title={title}
        onClose={resolve}
        dismissible={dismissible}
        maxWidth={maxWidth}
        testID={testID}
      >
        <View style={styles.alertContainer}>
          {content ? (
            <ScrollView
              style={[styles.messageScrollView, { maxHeight: maxContentHeight }]}
              contentContainerStyle={styles.scrollContent}
              testID={`${testID}-scroll-content`}
              nestedScrollEnabled={true}
              keyboardShouldPersistTaps="handled"
              showsVerticalScrollIndicator={true}
            >
              {content}
            </ScrollView>
          ) : message ? (
            <ScrollView
              style={[
                styles.messageScrollView,
                { maxHeight: maxContentHeight },
                isCodeOrJson && {
                  backgroundColor: theme.colors.background ?? '#F8FAFC',
                  borderColor: theme.colors.border ?? '#E2E8F0',
                },
              ]}
              contentContainerStyle={styles.scrollContent}
              testID={`${testID}-scroll-content`}
              nestedScrollEnabled={true}
              keyboardShouldPersistTaps="handled"
              showsVerticalScrollIndicator={true}
            >
              <Text
                testID={`${testID}-message`}
                style={[
                  styles.messageText,
                  { color: theme.colors.text },
                  isCodeOrJson && styles.codeText,
                ]}
                selectable={true}
              >
                {message}
              </Text>
            </ScrollView>
          ) : null}

          <TouchableOpacity
            testID={`${testID}-action-btn`}
            style={[
              styles.primaryBtn,
              {
                backgroundColor:
                  type === 'error'
                    ? '#EF4444'
                    : type === 'warning'
                    ? '#F59E0B'
                    : theme.colors.primary,
              },
            ]}
            onPress={resolve}
          >
            <Text style={styles.primaryBtnText}>{buttonText}</Text>
          </TouchableOpacity>
        </View>
      </AppAlertModal>
    );
  }

  // 2. Confirm Dialog
  if (modalState.modalType === 'confirm') {
    const { options, resolve } = modalState;
    return (
      <ConfirmDialog
        visible={true}
        title={options.title || 'Confirm Action'}
        message={options.message || 'Are you sure you want to proceed?'}
        confirmLabel={options.confirmLabel || 'Confirm'}
        cancelLabel={options.cancelLabel || 'Cancel'}
        isDestructive={options.isDestructive}
        onConfirm={() => resolve(true)}
        onCancel={() => resolve(false)}
        testID={options.testID || 'global-confirm-dialog'}
      />
    );
  }

  // 3. Bottom Sheet
  if (modalState.modalType === 'bottomSheet') {
    const { options, resolve } = modalState;
    return (
      <AppBottomSheet
        visible={true}
        title={options.title}
        showHeader={options.showHeader}
        dismissible={options.dismissible}
        draggable={options.draggable}
        maxHeightPercent={options.maxHeightPercent}
        onClose={resolve}
        testID={options.testID || 'global-bottom-sheet'}
      >
        {options.content}
      </AppBottomSheet>
    );
  }

  // 4. Image Confirm Modal
  if (modalState.modalType === 'imageConfirm') {
    const { options, resolve } = modalState;
    return (
      <ImageConfirmModal
        visible={true}
        title={options.title || 'Verify'}
        message={options.message || ''}
        confirmLabel={options.confirmLabel || 'Proceed'}
        cancelLabel={options.cancelLabel || 'Cancel'}
        visualType={options.visualType || 'big'}
        preset={options.preset}
        imageUri={options.imageUri}
        isDestructive={options.isDestructive}
        onConfirm={() => resolve(true)}
        onCancel={() => resolve(false)}
        testID={options.testID || 'global-image-confirm'}
      />
    );
  }

  // 5. Another Device Login Confirm Modal (Push / Security Alert)
  if (modalState.modalType === 'anotherDeviceLogin') {
    const { options, resolve } = modalState;
    return (
      <AnotherDeviceLoginConfirmModal
        visible={true}
        deviceName={options.deviceName}
        location={options.location}
        timestamp={options.timestamp}
        onConfirmItsMe={() => resolve(true)}
        onRejectNotMe={() => resolve(false)}
        onClose={() => resolve(false)}
        testID={options.testID || 'global-another-device-login'}
      />
    );
  }

  return null;
};

const styles = StyleSheet.create({
  alertContainer: {
    width: '100%',
  },
  messageScrollView: {
    width: '100%',
    borderRadius: 8,
    borderWidth: 1,
    borderColor: 'transparent',
    padding: 8,
    marginBottom: 16,
  },
  scrollContent: {
    paddingVertical: 4,
  },
  messageText: {
    fontSize: 14,
    lineHeight: 20,
  },
  codeText: {
    fontFamily: Platform.OS === 'ios' ? 'Menlo' : 'monospace',
    fontSize: 12,
    lineHeight: 18,
  },
  primaryBtn: {
    width: '100%',
    paddingVertical: 12,
    borderRadius: 10,
    alignItems: 'center',
    justifyContent: 'center',
  },
  primaryBtnText: {
    color: '#FFFFFF',
    fontWeight: '600',
    fontSize: 15,
  },
});

