import { useEffect, useRef } from 'react';
import {
  registerNetworkStrength,
  unregisterNetworkStrength,
  addNetworkStrengthListener,
  type NetworkStatusResult,
  registerUserInactivity,
  unregisterUserInactivity,
  addUserInactivityListener,
  type UserInactivityEvent,
  registerAppLifecycle,
  unregisterAppLifecycle,
  addAppLifecycleListener,
  type AppLifecycleEvent,
  registerSystemEvent,
  unregisterSystemEvent,
  addThemeModeListener,
  addBiometricChangeListener,
  addScreenRecordingChangeListener,
  SYSTEM_EVENT_NAMES,
  type ThemeModeEvent,
  type BiometricChangeEvent,
  type ScreenRecordingChangeEvent,
} from 'react-native-bizmob-plugin';
import { appLogger } from '@mfe/core/logger';
import { APP_EVENTS, defaultAppEventBus } from '@mfe/core/services';
import { toastUtil } from '@mfe/core/utils';

export interface UseGlobalPluginEventsOptions {
  /** Inactivity timeout in milliseconds (default: 60000 ms). */
  inactivityDurationMs?: number;
  /** Whether inactivity event repeats while user remains idle (default: true). */
  inactivityRepeat?: boolean;
  /** Whether to show a global toast when network strength/connectivity changes (default: true). */
  showNetworkToast?: boolean;
  onNetworkStrength?: (event: NetworkStatusResult) => void;
  onUserInactivity?: (event: UserInactivityEvent) => void;
  onAppLifecycle?: (event: AppLifecycleEvent) => void;
  onThemeMode?: (event: ThemeModeEvent) => void;
  onBiometricChange?: (event: BiometricChangeEvent) => void;
  onScreenRecordingChange?: (event: ScreenRecordingChangeEvent) => void;
}

const LOG_TAG = 'useGlobalPluginEvents';

function formatNetworkTypeLabel(event: NetworkStatusResult): string {
  const raw = event.type || event.network_type || 'network';
  if (raw === 'wifi') return 'Wi-Fi';
  if (raw === 'mobile_data') return 'Mobile Data';
  if (raw === 'ethernet') return 'Ethernet';
  return raw;
}

const NETWORK_OFFLINE_TOAST_ID = 'network-offline-toast';

type NetworkState = 'disconnected' | 'low' | 'connected';

function getNetworkState(event: NetworkStatusResult): NetworkState {
  if (!event.isConnected || event.signal_strength === 'none' || event.signal_strength === 'low') {
    return 'disconnected';
  }
  return 'connected';
}

function showNetworkStrengthToast(
  event: NetworkStatusResult,
  prevState: NetworkState | null
): void {
  const label = formatNetworkTypeLabel(event);
  const currentState = getNetworkState(event);

  if (currentState === 'disconnected') {
    toastUtil.error('No internet connection', {
      id: NETWORK_OFFLINE_TOAST_ID,
      duration: 0,
      showCloseButton: false,
    });
    return;
  }

  // Network is back — clear any sticky offline toast before showing status
  toastUtil.dismiss(NETWORK_OFFLINE_TOAST_ID);

  if (currentState === 'low') {
    toastUtil.warning(`Weak network signal (${label})`);
    return;
  }

  // Only show connected toast when recovering from a disconnected/lost state
  if (prevState === 'disconnected') {
    toastUtil.success(`Network connected (${label} · ${event.signal_strength})`);
  }
}

/**
 * Global native plugin event subscription hook.
 *
 * Registers and subscribes once at the application root to:
 * 1. Network strength (`onNetworkStrength`)
 * 2. User inactivity (`onUserInactivity`)
 * 3. App lifecycle (`onAppLifecycle`)
 * 4. System theme mode (`onThemeMode`)
 * 5. Biometric enrollment/availability change (`onBiometricChange`)
 * 6. Screen recording state change (`onScreenRecordingChange`)
 *
 * Each event is logged and broadcast through `defaultAppEventBus` so any remote
 * micro-frontend can react without coupling directly to native plugin modules.
 */
export function useGlobalPluginEvents(options: UseGlobalPluginEventsOptions = {}): void {
  const { inactivityDurationMs = 60000, inactivityRepeat = true } = options;

  const callbacksRef = useRef(options);
  callbacksRef.current = options;

  useEffect(() => {
    let prevNetworkState: NetworkState | null = null;

    // 1. Subscribe to native DeviceEventEmitter streams first so no early events are missed
    const networkSub = addNetworkStrengthListener((event) => {
      appLogger.i(LOG_TAG, '[onNetworkStrength]', event);
      defaultAppEventBus.publish(APP_EVENTS.NETWORK_STRENGTH_CHANGED, event);
      if (callbacksRef.current.showNetworkToast !== false) {
        showNetworkStrengthToast(event, prevNetworkState);
      }
      prevNetworkState = getNetworkState(event);
      callbacksRef.current.onNetworkStrength?.(event);
    });

    const inactivitySub = addUserInactivityListener((event) => {
      appLogger.w(LOG_TAG, '[onUserInactivity]', event);
      defaultAppEventBus.publish(APP_EVENTS.USER_INACTIVITY, event);
      callbacksRef.current.onUserInactivity?.(event);
    });

    const lifecycleSub = addAppLifecycleListener((event) => {
      appLogger.i(LOG_TAG, '[onAppLifecycle]', event);
      defaultAppEventBus.publish(APP_EVENTS.APP_LIFECYCLE_CHANGED, event);
      callbacksRef.current.onAppLifecycle?.(event);
    });

    const themeModeSub = addThemeModeListener((event) => {
      appLogger.i(LOG_TAG, '[onThemeMode]', event);
      defaultAppEventBus.publish(APP_EVENTS.THEME_MODE_CHANGED, event);
      callbacksRef.current.onThemeMode?.(event);
    });

    const biometricSub = addBiometricChangeListener((event) => {
      appLogger.w(LOG_TAG, '[onBiometricChange]', event);
      defaultAppEventBus.publish(APP_EVENTS.BIOMETRIC_CHANGED, event);
      callbacksRef.current.onBiometricChange?.(event);
    });

    // const screenRecordingSub = addScreenRecordingChangeListener((event) => {
    //   appLogger.w(LOG_TAG, '[onScreenRecordingChange]', event);
    //   defaultAppEventBus.publish(APP_EVENTS.SCREEN_RECORDING_CHANGED, event);
    //   callbacksRef.current.onScreenRecordingChange?.(event);
    // });

    // 2. Register native monitors (best-effort; safely catches on web/unsupported environments)
    const safeRegister = (name: string, fn: () => Promise<unknown>) => {
      Promise.resolve()
        .then(fn)
        .catch((err) => {
          appLogger.w(LOG_TAG, `Failed to register ${name}`, err);
        });
    };

    safeRegister('NETWORK_STRENGTH_PLUGIN', () => registerNetworkStrength());
    safeRegister('USER_INACTIVITY_PLUGIN', () =>
      registerUserInactivity({ durationMs: inactivityDurationMs, repeat: inactivityRepeat })
    );
    safeRegister('APP_LIFECYCLE_PLUGIN', () => registerAppLifecycle());
    safeRegister('SYSTEM_EVENTS_PLUGIN:onThemeMode', () =>
      registerSystemEvent(SYSTEM_EVENT_NAMES.THEME_MODE)
    );
    safeRegister('SYSTEM_EVENTS_PLUGIN:onBiometricChange', () =>
      registerSystemEvent(SYSTEM_EVENT_NAMES.BIOMETRIC)
    );
    safeRegister('SYSTEM_EVENTS_PLUGIN:onScreenRecordingChange', () =>
      registerSystemEvent(SYSTEM_EVENT_NAMES.SCREEN_RECORDING)
    );

    // 3. Clean up all listeners and unregister native monitors on unmount
    return () => {
      networkSub?.remove?.();
      inactivitySub?.remove?.();
      lifecycleSub?.remove?.();
      themeModeSub?.remove?.();
      biometricSub?.remove?.();
      // screenRecordingSub?.remove?.();

      const safeUnregister = (fn: () => Promise<unknown>) => {
        Promise.resolve()
          .then(fn)
          .catch(() => { });
      };

      safeUnregister(() => unregisterNetworkStrength());
      safeUnregister(() => unregisterUserInactivity());
      safeUnregister(() => unregisterAppLifecycle());
      safeUnregister(() => unregisterSystemEvent(SYSTEM_EVENT_NAMES.THEME_MODE));
      safeUnregister(() => unregisterSystemEvent(SYSTEM_EVENT_NAMES.BIOMETRIC));
      safeUnregister(() => unregisterSystemEvent(SYSTEM_EVENT_NAMES.SCREEN_RECORDING));
    };
  }, [inactivityDurationMs, inactivityRepeat]);
}
