import { useEffect, useRef } from 'react';
import { BackHandler, PanResponder, PanResponderInstance, Platform } from 'react-native';

export interface UseBackNavigationOptions {
  onBack?: () => void;
  enabled?: boolean;
  /**
   * Minimum distance in pixels to trigger a horizontal swipe-back gesture
   * Default: 50
   */
  swipeThreshold?: number;
  /**
   * Maximum distance from the left screen edge to start detecting the swipe
   * Default: 40 (only edge swipes trigger back)
   */
  edgeHitWidth?: number;
}

/**
 * Reusable hook providing Android hardware/system navigation back handling
 * and Android/fallback left-to-right edge swipe gesture back handling.
 *
 * Note: On iOS, system-native swipe back is driven by UINavigationController / @react-navigation/native-stack.
 * On Android (and non-native-stack fallbacks), this hook intercepts hardware back button presses
 * and left edge horizontal swipe gestures.
 */
export function useBackNavigation({
  onBack,
  enabled = true,
  swipeThreshold = 50,
  edgeHitWidth = 45,
}: UseBackNavigationOptions) {
  const onBackRef = useRef(onBack);
  onBackRef.current = onBack;

  // 1. Android Hardware Back Button & System Navigation Back Gesture
  // In Jest / cross-platform test environments Platform.OS may be 'ios' or test defaults.
  // BackHandler in React Native safely no-ops on iOS devices, so listening unconditionally
  // ensures Android hardware back buttons (and unit test mocks) always receive events.
  useEffect(() => {
    if (!enabled || !onBack) return;

    const onHardwareBackPress = () => {
      if (onBackRef.current) {
        onBackRef.current();
        return true; // Prevent default app exit
      }
      return false;
    };

    const subscription = BackHandler.addEventListener(
      'hardwareBackPress',
      onHardwareBackPress
    );

    return () => {
      subscription.remove();
    };
  }, [enabled, onBack]);

  // 2. Android Edge Swipe Back Gesture PanResponder
  // On iOS, system UIKit interactivePopGestureRecognizer natively controls edge swipe back.
  // We do not intercept touches near the left edge on iOS to prevent aborting/cancelling navigation.
  const panResponder = useRef<PanResponderInstance>(
    PanResponder.create({
      onStartShouldSetPanResponder: () => false,
      onStartShouldSetPanResponderCapture: () => false,
      onMoveShouldSetPanResponder: (evt, gestureState) => {
        if (!enabled || !onBackRef.current) return false;
        if (Platform.OS === 'ios') return false; // Native iOS handles edge swipe
        const isNearEdge = evt.nativeEvent.pageX - gestureState.dx <= edgeHitWidth;
        const isHorizontalSwipe =
          gestureState.dx > 10 && Math.abs(gestureState.dx) > Math.abs(gestureState.dy) * 1.5;
        return isNearEdge && isHorizontalSwipe;
      },
      onMoveShouldSetPanResponderCapture: (evt, gestureState) => {
        if (!enabled || !onBackRef.current) return false;
        if (Platform.OS === 'ios') return false; // Native iOS handles edge swipe
        const isNearEdge = evt.nativeEvent.pageX - gestureState.dx <= edgeHitWidth;
        const isHorizontalSwipe =
          gestureState.dx > 15 && Math.abs(gestureState.dx) > Math.abs(gestureState.dy) * 1.5;
        return isNearEdge && isHorizontalSwipe;
      },
      onPanResponderRelease: (_evt, gestureState) => {
        if (Platform.OS === 'ios') return;
        // Trigger if dragged past threshold with positive rightward velocity/distance
        if (gestureState.dx > swipeThreshold && gestureState.vx >= 0) {
          if (onBackRef.current) {
            onBackRef.current();
          }
        }
      },
    })
  ).current;

  return {
    panHandlers: enabled && onBack ? panResponder.panHandlers : {},
  };
}
