import React from 'react';
import { Platform, StyleSheet, View, ViewStyle, StyleProp } from 'react-native';

export interface AppBlurBackdropProps {
  style?: StyleProp<ViewStyle>;
  blurType?: 'xlight' | 'light' | 'dark' | 'extraDark' | 'regular' | 'prominent';
  blurAmount?: number;
  overlayColor?: string;
  testID?: string;
  children?: React.ReactNode;
}

/**
 * Universal blur backdrop component:
 * - On iOS & Android: Uses native @react-native-community/blur for authentic GPU-accelerated frosted glass.
 * - On Web: Uses standard CSS backdrop-filter: blur(...).
 */
export const AppBlurBackdrop: React.FC<AppBlurBackdropProps> = ({
  style,
  blurType = 'dark',
  blurAmount = 15,
  overlayColor,
  testID = 'app-blur-backdrop',
  children,
}) => {
  if (Platform.OS === 'web') {
    return (
      <View
        testID={testID}
        style={[
          StyleSheet.absoluteFillObject,
          styles.webBlur,
          {
            // @ts-ignore Web backdrop filter
            backdropFilter: `blur(${blurAmount}px)`,
            WebkitBackdropFilter: `blur(${blurAmount}px)`,
            backgroundColor: overlayColor || 'rgba(15, 23, 42, 0.45)',
          },
          style,
        ]}
      >
        {children}
      </View>
    );
  }

  // Native iOS / Android
  try {
    const blurModule = require('@react-native-community/blur');
    const BlurView = blurModule?.BlurView;
    if (BlurView) {
      const clampedAmount = Math.max(1, Math.min(blurAmount, 25));
      return (
        <BlurView
          testID={testID}
          pointerEvents="none"
          style={[StyleSheet.absoluteFillObject, style]}
          blurType={blurType}
          blurAmount={clampedAmount}
          blurRadius={clampedAmount}
          downsampleFactor={4}
          reducedTransparencyFallbackColor={overlayColor || 'rgba(15, 23, 42, 0.65)'}
          overlayColor={overlayColor || 'rgba(15, 23, 42, 0.35)'}
        >
          {children}
        </BlurView>
      );
    }
  } catch {
    // Fallback below if native module is unavailable
  }

  return (
    <View
      testID={testID}
      pointerEvents="none"
      style={[
        StyleSheet.absoluteFillObject,
        { backgroundColor: overlayColor || 'rgba(15, 23, 42, 0.65)' },
        style,
      ]}
    >
      {children}
    </View>
  );
};

const styles = StyleSheet.create({
  webBlur: {
    ...StyleSheet.absoluteFillObject,
  },
});

