import { useState, useEffect, useCallback } from 'react';
import {
  DashboardSummaryDTO,
  DashboardPeriodTab,
  DebtorItemDTO,
} from '../models/DashboardModel';
import {
  IDashboardService,
  DashboardService,
} from '../services/DashboardService';

export interface UseDashboardViewModelProps {
  dashboardService?: IDashboardService;
  useMock?: boolean;
}

export function useDashboardViewModel({
  dashboardService = DashboardService.getInstance(),
  useMock = true,
}: UseDashboardViewModelProps = {}) {
  const [activeSubTab, setActiveSubTab] = useState<DashboardPeriodTab>('today');
  const [summary, setSummary] = useState<DashboardSummaryDTO>({
    userName: 'Pang Phanna',
    greeting: 'Good Evening',
    otpSupportPhone: '012 345 787',
    authStats: {
      needMyApproval: 1,
      myApproved: 52,
    },
    todoHistory: {
      approved: 20,
      waiting: 7,
      returned: 1,
      rejected: 3,
    },
    debtorMetrics: {
      today: {
        goalOfDebtor: 0,
        visitedDebtor: 0,
        goalOfAmountMasked: '* * *',
        currencyCode: 'USD',
      },
      week: {
        goalOfDebtor: 5,
        visitedDebtor: 3,
        goalOfAmountMasked: '* * *',
        currencyCode: 'USD',
      },
      month: {
        goalOfDebtor: 18,
        visitedDebtor: 14,
        goalOfAmountMasked: '* * *',
        currencyCode: 'USD',
      },
    },
    salesKpi: {
      totalApplications: 142,
      approvedCount: 118,
      pendingReviewCount: 19,
      totalDisbursedAmount: 485000,
      currency: 'USD',
      monthlyTargetAmount: 600000,
      targetAchievementPercent: 80.8,
    },
  });

  const [debtorList, setDebtorList] = useState<DebtorItemDTO[]>([]);
  const [isRefreshing, setIsRefreshing] = useState<boolean>(false);

  const loadDashboardData = useCallback(async () => {
    setIsRefreshing(true);
    try {
      const [summaryData, debtors] = await Promise.all([
        dashboardService.getDashboardSummary(useMock),
        dashboardService.getDebtorList(useMock),
      ]);
      if (summaryData) {
        setSummary(summaryData);
      }
      if (debtors) {
        setDebtorList(debtors);
      }
    } finally {
      setIsRefreshing(false);
    }
  }, [dashboardService, useMock]);

  useEffect(() => {
    loadDashboardData();
  }, [loadDashboardData]);

  const currentDebtorMetric = summary.debtorMetrics?.[activeSubTab] || {
    goalOfDebtor: 0,
    visitedDebtor: 0,
    goalOfAmountMasked: '* * *',
    currencyCode: 'USD',
  };

  return {
    activeSubTab,
    setActiveSubTab,
    summary,
    debtorList,
    currentDebtorMetric,
    isRefreshing,
    handleRefresh: loadDashboardData,
  };
}
