import React, { useState } from 'react';
import {
  View,
  Text,
  TouchableOpacity,
  StyleSheet,
  Modal,
  Image,
  ImageSourcePropType,
  TouchableWithoutFeedback,
  ScrollView,
  Dimensions,
} from 'react-native';

export type ImageConfirmVisualType = 'big' | 'small' | 'icon';
export type ImageConfirmPreset = 'loan-doc' | 'wallet' | 'success' | 'warning' | 'alert' | 'logout' | 'popper';
export type ImageConfirmButtonLayout = 'row' | 'column';

export interface ImageConfirmModalProps {
  visible: boolean;
  onClose: () => void;
  title: string;
  message?: string;
  /**
   * Optional custom highlight content rendered between title/message and checkbox.
   * Useful for large amount displays (e.g. 500.000.000 VND), interest rate badges, or rich cards (ML-004).
   */
  children?: React.ReactNode;
  /**
   * Visual presentation style of the header image/icon:
   * - 'big': 3D hero illustration (~120-130px), e.g. Incomplete Loan Application (ML-003) or Celebration Popper (ML-004)
   * - 'small': Compact illustration (~64-72px), e.g. warning, wallet or document thumbnail
   * - 'icon': Circular badge with icon (~44px), e.g. system alert or logout dialog
   */
  imageType?: ImageConfirmVisualType;
  /**
   * Built-in vector presets or custom image/render prop
   */
  preset?: ImageConfirmPreset;
  /**
   * Optional custom Image source if not using preset
   */
  imageSource?: ImageSourcePropType;
  /**
   * Optional custom render function for custom SVG / animated / vector illustration
   */
  renderCustomImage?: () => React.ReactNode;
  /**
   * Button labels
   */
  confirmText?: string;
  cancelText?: string;
  /**
   * Button orientation layout:
   * - 'row': Side-by-side buttons (Cancel on left, Continue on right)
   * - 'column': Stacked buttons (Primary button on top, secondary/close link on bottom like ML-004)
   */
  buttonLayout?: ImageConfirmButtonLayout;
  /**
   * Handlers
   */
  onConfirm: (doNotShowAgain?: boolean) => void;
  onCancel?: () => void;
  /**
   * "Do not show this notice again" checkbox options (ML-003, ML-004)
   */
  showDoNotShowAgain?: boolean;
  doNotShowAgainText?: string;
  initialDoNotShowAgain?: boolean;
  /**
   * Styling overrides
   */
  confirmButtonColor?: string;
  isDestructive?: boolean;
  /**
   * Maximum dialog height percentage (default 85% of screen height)
   */
  maxHeight?: number | string;
  testID?: string;
}

export const ImageConfirmModal: React.FC<ImageConfirmModalProps> = ({
  visible,
  onClose,
  title,
  message,
  children,
  imageType = 'big',
  preset = 'loan-doc',
  imageSource,
  renderCustomImage,
  confirmText = 'Continue',
  cancelText = 'Cancel',
  buttonLayout = 'row',
  onConfirm,
  onCancel,
  showDoNotShowAgain = false,
  doNotShowAgainText = 'Do not show this notice again',
  initialDoNotShowAgain = false,
  confirmButtonColor,
  isDestructive = false,
  testID = 'image-confirm-modal',
}) => {
  const [doNotShowAgain, setDoNotShowAgain] = useState<boolean>(initialDoNotShowAgain);

  const screenHeight = Dimensions.get('window').height;
  const maxCardHeight = Math.min(screenHeight * 0.88, 620);

  const handleCancel = () => {
    if (onCancel) {
      onCancel();
    } else {
      onClose();
    }
  };

  const handleConfirm = () => {
    onConfirm(doNotShowAgain);
  };

  const renderIllustration = () => {
    if (renderCustomImage) {
      return renderCustomImage();
    }

    if (imageSource) {
      const imgSize = imageType === 'big' ? 120 : imageType === 'small' ? 64 : 36;
      return (
        <Image
          source={imageSource}
          style={{ width: imgSize, height: imgSize }}
          resizeMode="contain"
          testID={`${testID}-custom-image`}
        />
      );
    }

    // Render presets based on imageType and preset
    if (imageType === 'big') {
      return renderBigPreset(preset, testID);
    } else if (imageType === 'small') {
      return renderSmallPreset(preset, testID);
    } else {
      return renderIconPreset(preset, isDestructive, testID);
    }
  };

  return (
    <Modal
      transparent
      animationType="fade"
      visible={visible}
      onRequestClose={handleCancel}
    >
      <TouchableWithoutFeedback onPress={handleCancel}>
        <View testID={testID} style={styles.backdrop}>
          <TouchableWithoutFeedback>
            <View style={[styles.dialogCard, { maxHeight: maxCardHeight }]}>
              <ScrollView
                style={styles.cardScrollView}
                contentContainerStyle={styles.cardScrollContent}
                showsVerticalScrollIndicator={false}
                bounces={false}
              >
                {/* Illustration / Image Header */}
                <View style={[styles.imageContainer, getImageContainerSpacing(imageType)]}>
                  {renderIllustration()}
                </View>

                {/* Title */}
                <Text testID={`${testID}-title`} style={styles.title}>
                  {title}
                </Text>

                {/* Message (Optional) */}
                {message ? (
                  <Text testID={`${testID}-message`} style={styles.message}>
                    {message}
                  </Text>
                ) : null}

                {/* Custom Content Slot (e.g. 500,000,000 VND Top-Up Announcement) */}
                {children ? <View style={styles.childrenContainer}>{children}</View> : null}

                {/* Optional "Do not show this notice again" checkbox */}
                {showDoNotShowAgain ? (
                  <TouchableOpacity
                    testID={`${testID}-checkbox`}
                    style={styles.checkboxContainer}
                    onPress={() => setDoNotShowAgain(!doNotShowAgain)}
                    activeOpacity={0.8}
                  >
                    <View
                      testID={`${testID}-checkbox-box`}
                      style={[styles.checkboxBox, doNotShowAgain && styles.checkboxBoxChecked]}
                    >
                      {doNotShowAgain ? <Text style={styles.checkmark}>✓</Text> : null}
                    </View>
                    <Text style={styles.checkboxLabel}>{doNotShowAgainText}</Text>
                  </TouchableOpacity>
                ) : null}

                {/* Action Buttons */}
                {buttonLayout === 'column' ? (
                  <View style={styles.buttonCol}>
                    {/* Primary Confirm Button */}
                    <TouchableOpacity
                      testID={`${testID}-confirm`}
                      style={[
                        styles.button,
                        styles.confirmButton,
                        confirmButtonColor ? { backgroundColor: confirmButtonColor } : null,
                        isDestructive && !confirmButtonColor ? styles.destructiveButton : null,
                      ]}
                      onPress={handleConfirm}
                      activeOpacity={0.8}
                    >
                      <Text style={styles.confirmText}>{confirmText}</Text>
                    </TouchableOpacity>

                    {/* Secondary Link / Button */}
                    {cancelText ? (
                      <TouchableOpacity
                        testID={`${testID}-cancel`}
                        style={styles.cancelLinkButton}
                        onPress={handleCancel}
                        activeOpacity={0.7}
                      >
                        <Text style={styles.cancelLinkText}>{cancelText}</Text>
                      </TouchableOpacity>
                    ) : null}
                  </View>
                ) : (
                  <View style={styles.buttonRow}>
                    {cancelText ? (
                      <TouchableOpacity
                        testID={`${testID}-cancel`}
                        style={[styles.button, styles.cancelButton]}
                        onPress={handleCancel}
                        activeOpacity={0.8}
                      >
                        <Text style={styles.cancelText}>{cancelText}</Text>
                      </TouchableOpacity>
                    ) : null}

                    <TouchableOpacity
                      testID={`${testID}-confirm`}
                      style={[
                        styles.button,
                        styles.confirmButton,
                        confirmButtonColor ? { backgroundColor: confirmButtonColor } : null,
                        isDestructive && !confirmButtonColor ? styles.destructiveButton : null,
                        !cancelText ? { flex: 1 } : null,
                      ]}
                      onPress={handleConfirm}
                      activeOpacity={0.8}
                    >
                      <Text style={styles.confirmText}>{confirmText}</Text>
                    </TouchableOpacity>
                  </View>
                )}
              </ScrollView>
            </View>
          </TouchableWithoutFeedback>
        </View>
      </TouchableWithoutFeedback>
    </Modal>
  );
};

function getImageContainerSpacing(type: ImageConfirmVisualType) {
  switch (type) {
    case 'big':
      return { marginTop: 4, marginBottom: 16 };
    case 'small':
      return { marginTop: 6, marginBottom: 14 };
    case 'icon':
      return { marginTop: 8, marginBottom: 12 };
  }
}

// -------------------------------------------------------------
// Big 3D Preset Vector Renderers (ML-003, ML-004)
// -------------------------------------------------------------
function renderBigPreset(preset: ImageConfirmPreset, testID: string) {
  switch (preset) {
    case 'loan-doc':
      return (
        <View testID={`${testID}-preset-big-loan-doc`} style={styles.big3dContainer}>
          {/* 3D Clipboard Backing */}
          <View style={styles.clipboardBack}>
            {/* Top Clip */}
            <View style={styles.clipboardClip}>
              <View style={styles.clipboardClipInner} />
            </View>

            {/* Document Lines */}
            <View style={styles.docLineLong} />
            <View style={styles.docLineShort} />
            <View style={styles.docLineMedium} />
            <View style={styles.docLineShort} />

            {/* Secondary Badge Block */}
            <View style={styles.docSmallBadge} />
            <View style={styles.docSmallBadge2} />
          </View>

          {/* Golden Coin with Dollar Icon */}
          <View style={styles.goldCoinOuter}>
            <View style={styles.goldCoinInner}>
              <Text style={styles.goldCoinSymbol}>$</Text>
            </View>
          </View>
        </View>
      );

    case 'popper':
      return (
        <View testID={`${testID}-preset-big-popper`} style={styles.big3dContainer}>
          {/* Confetti Elements */}
          <View style={styles.popperStarTop}>
            <Text style={styles.popperStarText}>★</Text>
          </View>
          <View style={styles.popperSparkle1} />
          <View style={styles.popperSparkle2} />
          <View style={styles.popperRibbon1} />
          <View style={styles.popperRibbon2} />
          <View style={styles.popperRibbon3} />

          {/* Party Cone / Popper */}
          <View style={styles.popperConeWrapper}>
            <View style={styles.popperConeFlap} />
            <View style={styles.popperConeBody}>
              <View style={styles.popperStripe1} />
              <View style={styles.popperStripe2} />
              <View style={styles.popperStripe3} />
            </View>
          </View>
        </View>
      );

    case 'wallet':
      return (
        <View testID={`${testID}-preset-big-wallet`} style={styles.big3dContainer}>
          <View style={styles.walletBody}>
            <View style={styles.walletFlap}>
              <View style={styles.walletButtonBadge}>
                <Text style={styles.walletButtonIcon}>★</Text>
              </View>
            </View>
            <View style={styles.walletCashPeek}>
              <Text style={styles.walletCashText}>VNĐ</Text>
            </View>
          </View>
        </View>
      );

    case 'success':
      return (
        <View testID={`${testID}-preset-big-success`} style={styles.big3dContainer}>
          <View style={styles.successShield}>
            <Text style={styles.successShieldCheck}>✓</Text>
          </View>
        </View>
      );

    case 'warning':
    case 'alert':
      return (
        <View testID={`${testID}-preset-big-warning`} style={styles.big3dContainer}>
          <View style={styles.warningClock}>
            <Text style={styles.warningExclamation}>!</Text>
          </View>
        </View>
      );

    case 'logout':
      return (
        <View testID={`${testID}-preset-big-logout`} style={styles.big3dContainer}>
          <View style={styles.logoutCircleBadge}>
            <Text style={styles.logoutIcon}>⎋</Text>
          </View>
        </View>
      );
  }
}

// -------------------------------------------------------------
// Small Preset Renderers (~64px)
// -------------------------------------------------------------
function renderSmallPreset(preset: ImageConfirmPreset, testID: string) {
  const isDanger = preset === 'warning' || preset === 'alert';
  const isSuccess = preset === 'success';

  return (
    <View
      testID={`${testID}-preset-small`}
      style={[
        styles.smallBadgeContainer,
        isDanger && styles.smallBadgeDanger,
        isSuccess && styles.smallBadgeSuccess,
      ]}
    >
      <Text
        style={[
          styles.smallBadgeIconText,
          isDanger && { color: '#E7252B' },
          isSuccess && { color: '#00A862' },
        ]}
      >
        {preset === 'loan-doc'
          ? '📄'
          : preset === 'popper'
          ? '🎉'
          : preset === 'wallet'
          ? '💳'
          : preset === 'success'
          ? '✓'
          : preset === 'logout'
          ? '⎋'
          : '!'}
      </Text>
    </View>
  );
}

// -------------------------------------------------------------
// Icon Preset Renderers (~44px)
// -------------------------------------------------------------
function renderIconPreset(preset: ImageConfirmPreset, isDestructive: boolean, testID: string) {
  const isDanger = isDestructive || preset === 'warning' || preset === 'alert' || preset === 'logout';
  const isSuccess = preset === 'success';

  return (
    <View
      testID={`${testID}-preset-icon`}
      style={[
        styles.iconCircleBadge,
        isDanger && styles.iconDangerBadge,
        isSuccess && styles.iconSuccessBadge,
      ]}
    >
      <Text
        style={[
          styles.iconText,
          isDanger && { color: '#E7252B' },
          isSuccess && { color: '#00A862' },
        ]}
      >
        {preset === 'loan-doc'
          ? '📋'
          : preset === 'popper'
          ? '🎉'
          : preset === 'wallet'
          ? '💰'
          : preset === 'success'
          ? '✓'
          : preset === 'logout'
          ? '⎋'
          : '!'}
      </Text>
    </View>
  );
}

