import React, { useState, useRef } from 'react';
import {
  View,
  Text,
  TextInput,
  TouchableOpacity,
  ScrollView,
  StyleSheet,
  Dimensions,
} from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { useTheme } from '@mfe/core/theme/ThemeContext';
import { useKeyboardInfo } from '../hooks/useKeyboardInfo';
import { AppBottomSheet } from './AppBottomSheet';

export interface CommentItem {
  id: string;
  authorName: string;
  /** Short initials shown in avatar (derived from name when omitted) */
  authorInitials?: string;
  message: string;
  /** Pre-formatted timestamp, e.g. "31/10 09:02" */
  timestamp: string;
  replies?: CommentItem[];
}

export interface CommentListModalProps {
  visible: boolean;
  onClose: () => void;
  comments: CommentItem[];
  /** Called when user submits text. parentId is set when replying to a comment. */
  onSend: (text: string, parentId?: string) => void;
  title?: string;
  placeholder?: string;
  replyLabel?: string;
  /** Sheet max height as a fraction of screen height (default 0.88) */
  maxHeightPercent?: number;
  testID?: string;
}

// Bottom-sheet comment thread (Application comments).
// Composed directly on top of shared AppBottomSheet for standardized gestures, drag handles, and animation.
// See docs/technical/issues/keyboard-and-input/modal-input-hidden-behind-keyboard.md
export const CommentListModal: React.FC<CommentListModalProps> = ({
  visible,
  onClose,
  comments,
  onSend,
  title = 'Comments',
  placeholder = 'Write a comment...',
  replyLabel = 'Reply',
  maxHeightPercent = 0.88,
  testID = 'comment-list-modal',
}) => {
  const { theme } = useTheme();
  const insets = useSafeAreaInsets();
  const [text, setText] = useState('');
  const [replyTo, setReplyTo] = useState<CommentItem | null>(null);
  const scrollRef = useRef<any>(null);
  const kb = useKeyboardInfo(visible);

  const totalCount = comments.reduce((n, c) => n + 1 + (c.replies?.length ?? 0), 0);
  const palette = [
    { fg: theme.colors.info, bg: theme.colors.infoBg },
    { fg: theme.colors.error, bg: theme.colors.errorBg },
    { fg: theme.colors.success, bg: theme.colors.successBg },
  ];

  const getInitials = (c: CommentItem) =>
    (
      c.authorInitials ||
      c.authorName
        .split(' ')
        .filter(Boolean)
        .map((w) => w[0])
        .slice(0, 2)
        .join('')
    ).toUpperCase();

  const handleClose = () => {
    setText('');
    setReplyTo(null);
    onClose();
  };

  const handleSend = () => {
    const trimmed = text.trim();
    if (!trimmed) return;
    onSend(trimmed, replyTo?.id);
    setText('');
    setReplyTo(null);
  };

  const renderComment = (c: CommentItem, colorIndex: number, isReply: boolean, canReply: boolean) => {
    const tone = palette[colorIndex % palette.length];
    return (
      <View
        key={c.id}
        testID={`${testID}-item-${c.id}`}
        style={[styles.commentRow, isReply && styles.replyRow]}
      >
        <View style={[styles.avatar, { backgroundColor: tone.bg }]}>
          <Text style={[styles.avatarText, { color: tone.fg }]}>{getInitials(c)}</Text>
        </View>
        <View style={styles.commentBody}>
          <View style={styles.metaRow}>
            <Text
              numberOfLines={1}
              style={[styles.author, { color: theme.colors.text, fontFamily: theme.typography.fontFamilyBold }]}
            >
              {c.authorName}
            </Text>
            <Text style={[styles.timestamp, { color: theme.colors.textSubtle }]}>{c.timestamp}</Text>
          </View>
          <View
            style={[
              styles.bubble,
              { backgroundColor: isReply ? theme.colors.errorBg : theme.colors.background, borderRadius: theme.radius.lg },
            ]}
          >
            <Text style={[styles.message, { color: theme.colors.text }]}>{c.message}</Text>
          </View>
          {canReply ? (
            <TouchableOpacity
              testID={`${testID}-reply-${c.id}`}
              onPress={() => setReplyTo(c)}
              hitSlop={{ top: 8, bottom: 8, left: 8, right: 8 }}
              accessibilityRole="button"
            >
              <Text style={[styles.replyLink, { color: theme.colors.secondary }]}>{replyLabel}</Text>
            </TouchableOpacity>
          ) : null}
        </View>
      </View>
    );
  };

  return (
    <AppBottomSheet
      visible={visible}
      onClose={handleClose}
      title={`${title} (${totalCount})`}
      maxHeightPercent={maxHeightPercent}
      contentStyle={{ paddingHorizontal: 0, flex: 1, minHeight: 280 }}
      style={{
        height: Math.round(Dimensions.get('window').height * maxHeightPercent),
        paddingHorizontal: 0,
        paddingBottom: 0,
      }}
      footerComponent={
        <View
          style={[
            styles.composer,
            {
              borderTopColor: theme.colors.borderLight,
              paddingBottom: kb ? 12 : Math.max(insets.bottom, 12),
            },
          ]}
        >
          {replyTo ? (
            <View style={styles.replyingRow} testID={`${testID}-replying`}>
              <Text numberOfLines={1} style={[styles.replyingText, { color: theme.colors.textMuted }]}>
                {`${replyLabel}: ${replyTo.authorName}`}
              </Text>
              <TouchableOpacity testID={`${testID}-cancel-reply`} onPress={() => setReplyTo(null)}>
                <Text style={[styles.replyingCancel, { color: theme.colors.textSubtle }]}>✕</Text>
              </TouchableOpacity>
            </View>
          ) : null}
          <View style={styles.inputRow}>
            <TextInput
              testID={`${testID}-input`}
              value={text}
              onChangeText={setText}
              placeholder={placeholder}
              placeholderTextColor={theme.colors.textSubtle}
              keyboardType="default"
              multiline
              style={[
                styles.input,
                { backgroundColor: theme.colors.background, color: theme.colors.text, borderRadius: theme.radius.full },
              ]}
            />
            <TouchableOpacity
              testID={`${testID}-send`}
              onPress={handleSend}
              disabled={!text.trim()}
              activeOpacity={0.8}
              accessibilityRole="button"
              accessibilityLabel="Send"
              style={[
                styles.sendBtn,
                { backgroundColor: theme.colors.primaryDark, opacity: text.trim() ? 1 : 0.5 },
              ]}
            >
              <Text style={styles.sendIcon}>➤</Text>
            </TouchableOpacity>
          </View>
        </View>
      }
      testID={testID}
    >
      <ScrollView
        ref={scrollRef}
        onLayout={() => {
          if (kb) scrollRef.current?.scrollToEnd({ animated: false });
        }}
        style={styles.list}
        contentContainerStyle={styles.listContent}
        keyboardShouldPersistTaps="handled"
      >
        {comments.map((c, i) => (
          <View key={c.id} style={styles.thread}>
            {renderComment(c, i, false, true)}
            {(c.replies ?? []).map((r, ri) => renderComment(r, i + ri + 1, true, false))}
          </View>
        ))}
      </ScrollView>
    </AppBottomSheet>
  );
};

const styles = StyleSheet.create({
  list: { flex: 1 },
  listContent: { paddingHorizontal: 20, paddingBottom: 16 },
  thread: { marginBottom: 16 },
  commentRow: { flexDirection: 'row', alignItems: 'flex-start' },
  replyRow: { marginTop: 8, marginLeft: 40 },
  avatar: {
    width: 32,
    height: 32,
    borderRadius: 16,
    alignItems: 'center',
    justifyContent: 'center',
    marginRight: 10,
  },
  avatarText: { fontSize: 11, fontWeight: '800' },
  commentBody: { flex: 1 },
  metaRow: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginBottom: 4 },
  author: { fontSize: 13, fontWeight: '700', flexShrink: 1, paddingRight: 8 },
  timestamp: { fontSize: 11 },
  bubble: { paddingHorizontal: 12, paddingVertical: 10 },
  message: { fontSize: 13, lineHeight: 19 },
  replyLink: { fontSize: 12, fontWeight: '700', marginTop: 6 },
  composer: {
    borderTopWidth: 1,
    paddingHorizontal: 20,
    paddingTop: 12,
    backgroundColor: '#FFFFFF',
  },
  replyingRow: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginBottom: 8 },
  replyingText: { fontSize: 12, flex: 1 },
  replyingCancel: { fontSize: 14, paddingLeft: 8 },
  inputRow: { flexDirection: 'row', alignItems: 'center' },
  input: {
    flex: 1,
    minHeight: 44,
    maxHeight: 96,
    paddingHorizontal: 16,
    paddingVertical: 10,
    fontSize: 14,
    marginRight: 10,
  },
  sendBtn: { width: 44, height: 44, borderRadius: 22, alignItems: 'center', justifyContent: 'center' },
  sendIcon: { color: '#FFFFFF', fontSize: 16 },
});
