import React, { useState } from 'react';
import {
  TouchableOpacity,
  Text,
  ActivityIndicator,
  StyleSheet,
  ViewStyle,
  TextStyle,
  View,
  LayoutChangeEvent,
  Platform,
} from 'react-native';
import Svg, { Defs, LinearGradient as SvgLinearGradient, Stop, Rect } from 'react-native-svg';
import { useTheme } from '@mfe/core/theme/ThemeContext';

export type ButtonVariant =
  | 'primary'
  | 'secondary'
  | 'outline'
  | 'danger'
  | 'text'
  | 'gradient'
  | 'ghost';

export type ButtonSize = 'sm' | 'md' | 'lg' | 'small' | 'xs';
export type ButtonShape = 'rectangle' | 'rounded' | 'circle' | 'pill';

export interface GradientColorStop {
  color: string;
  offset?: string | number;
  opacity?: number;
}

export interface AppButtonProps {
  /**
   * Text label of the button. Optional when rendering an icon-only or circle button.
   */
  title?: string;
  onPress: () => void;
  variant?: ButtonVariant;
  size?: ButtonSize;
  disabled?: boolean;
  loading?: boolean;
  isLoading?: boolean;
  testID?: string;
  style?: ViewStyle;
  textStyle?: TextStyle;
  /**
   * Leading or trailing icon element. Also used as center icon for circle / icon-only buttons.
   */
  icon?: React.ReactNode;
  iconPosition?: 'left' | 'right' | 'center';
  /**
   * If true, applies an ultra-rounded pill shape (e.g. borderRadius: 9999).
   */
  rounded?: boolean;
  /**
   * Button geometry shape:
   * - 'rectangle': Standard rectangular with theme corner radius.
   * - 'rounded': Soft medium radius.
   * - 'pill': Full capsule pill (borderRadius: 9999).
   * - 'circle': Equal width & height perfect circle (ideal for icon buttons or floating actions).
   */
  shape?: ButtonShape;
  /**
   * Explicit border radius override (e.g. 0, 8, 16, 24). Overrides default theme radius & shape.
   */
  borderRadius?: number;
  /**
   * When true, formats the button as a 1:1 circle button. Alias for shape="circle".
   */
  circle?: boolean;
  /**
   * Custom diameter for circle button (defaults to standard size height: sm=36, md=48, lg=56, xs=28).
   */
  circleSize?: number;
  /**
   * Gradient color stops when variant="gradient" or when gradientColors is provided.
   * e.g. ['#E7252B', '#B91C1C'] or [{ color: '#1F5FA8' }, { color: '#0F172A' }]
   */
  gradientColors?: string[];
  /**
   * Gradient angle orientation: 'horizontal' (left to right) | 'vertical' (top to bottom) | 'diagonal'.
   */
  gradientDirection?: 'horizontal' | 'vertical' | 'diagonal';
  /**
   * Children prop for arbitrary nested content or custom layout.
   */
  children?: React.ReactNode;
}

export const AppButton: React.FC<AppButtonProps> = ({
  title,
  onPress,
  variant = 'primary',
  size = 'md',
  disabled = false,
  loading = false,
  isLoading = false,
  testID = 'app-button',
  style,
  textStyle,
  icon,
  iconPosition = 'left',
  rounded = false,
  shape,
  borderRadius,
  circle = false,
  circleSize,
  gradientColors,
  gradientDirection = 'horizontal',
  children,
}) => {
  const { theme } = useTheme();
  const [layoutSize, setLayoutSize] = useState({ width: 0, height: 0 });

  const isBusy = loading || isLoading;
  const isInteractive = !disabled && !isBusy;
  const normalizedSize = size === 'small' ? 'sm' : size;

  // Resolve shape
  const isCircle = circle || shape === 'circle';
  const isPill = rounded || shape === 'pill';
  const isGradientVariant = variant === 'gradient' || (Boolean(gradientColors) && variant !== 'outline' && variant !== 'text');

  const handlePress = () => {
    if (!isInteractive) return;
    onPress();
  };

  const handleLayout = (e: LayoutChangeEvent) => {
    const { width, height } = e.nativeEvent.layout;
    if (width !== layoutSize.width || height !== layoutSize.height) {
      setLayoutSize({ width, height });
    }
  };

  // Determine standard dimension for sizes
  const getDefaultDimension = (): number => {
    switch (normalizedSize) {
      case 'xs':
        return 28;
      case 'sm':
        return 36;
      case 'lg':
        return 56;
      case 'md':
      default:
        return 48;
    }
  };

  const resolvedCircleDimension = circleSize || getDefaultDimension();

  // Determine border radius
  const getResolvedBorderRadius = (): number => {
    if (typeof borderRadius === 'number') {
      return borderRadius;
    }
    if (isCircle) {
      return Math.round(resolvedCircleDimension / 2);
    }
    if (isPill) {
      return 9999;
    }
    if (shape === 'rounded') {
      return theme?.radius?.lg ?? 12;
    }
    return theme?.radius?.md ?? 8;
  };

  const finalBorderRadius = getResolvedBorderRadius();

  // Color mapping
  const getDynamicStyles = () => {
    let bg = theme?.colors?.primary || '#E7252B';
    let textColor = '#FFFFFF';
    let borderColor = 'transparent';
    let borderWidth = 0;

    switch (variant) {
      case 'secondary':
        bg = theme?.colors?.secondary || '#1F5FA8';
        textColor = '#FFFFFF';
        break;
      case 'outline':
        bg = 'transparent';
        textColor = theme?.colors?.primary || '#E7252B';
        borderColor = theme?.colors?.primary || '#E7252B';
        borderWidth = 1.5;
        break;
      case 'text':
      case 'ghost':
        bg = 'transparent';
        textColor = theme?.colors?.primary || '#E7252B';
        break;
      case 'danger':
        bg = theme?.colors?.error || '#E7252B';
        textColor = '#FFFFFF';
        break;
      case 'gradient':
        bg = 'transparent';
        textColor = '#FFFFFF';
        break;
      case 'primary':
      default:
        bg = theme?.colors?.primary || '#E7252B';
        textColor = '#FFFFFF';
        break;
    }

    if (disabled) {
      bg = theme?.colors?.background || '#F4F5F7';
      textColor = theme?.colors?.textSubtle || '#7B8494';
      borderColor = theme?.colors?.border || '#E2E5EB';
      borderWidth = variant === 'outline' ? 1 : 0;
    }

    return {
      container: {
        backgroundColor: isGradientVariant && !disabled ? 'transparent' : bg,
        borderRadius: finalBorderRadius,
        borderColor,
        borderWidth,
      },
      text: {
        color: textColor,
        fontFamily: theme?.typography?.fontFamilyBold || 'Pretendard-Bold',
      },
    };
  };

  const dynamic = getDynamicStyles();

  // Default gradient color sets if none passed
  const resolvedGradientColors = gradientColors || [
    theme?.colors?.primary || '#E7252B',
    theme?.colors?.primaryDark || '#B91C1C',
  ];

  // Compute gradient SVG coordinates
  const getGradientCoords = () => {
    switch (gradientDirection) {
      case 'vertical':
        return { x1: '0%', y1: '0%', x2: '0%', y2: '100%' };
      case 'diagonal':
        return { x1: '0%', y1: '0%', x2: '100%', y2: '100%' };
      case 'horizontal':
      default:
        return { x1: '0%', y1: '0%', x2: '100%', y2: '0%' };
    }
  };

  const coords = getGradientCoords();

  // Render gradient background if applicable
  const renderGradientBackground = () => {
    if (!isGradientVariant || disabled) return null;

    // Use Web CSS linear-gradient for seamless SSR and sharp rendering on web
    if (Platform.OS === 'web') {
      const dir =
        gradientDirection === 'vertical'
          ? 'to bottom'
          : gradientDirection === 'diagonal'
          ? '135deg'
          : 'to right';
      const webGradientStyle: ViewStyle = {
        position: 'absolute',
        top: 0,
        left: 0,
        right: 0,
        bottom: 0,
        borderRadius: finalBorderRadius,
        // @ts-ignore - Webpack/react-native-web background-image support
        backgroundImage: `linear-gradient(${dir}, ${resolvedGradientColors.join(', ')})`,
      };
      return <View style={webGradientStyle} pointerEvents="none" testID={`${testID}-gradient-bg`} />;
    }

    // Native platform SVG gradient mask
    const width = layoutSize.width || (isCircle ? resolvedCircleDimension : 200);
    const height = layoutSize.height || (isCircle ? resolvedCircleDimension : getDefaultDimension());
    const gradientId = `btn-grad-${testID}-${coords.x1}-${coords.y2}`;

    return (
      <View
        pointerEvents="none"
        style={[
          StyleSheet.absoluteFill,
          { borderRadius: finalBorderRadius, overflow: 'hidden' },
        ]}
        testID={`${testID}-gradient-bg`}
      >
        <Svg width="100%" height="100%" viewBox={`0 0 ${width} ${height}`}>
          <Defs>
            <SvgLinearGradient id={gradientId} x1={coords.x1} y1={coords.y1} x2={coords.x2} y2={coords.y2}>
              {resolvedGradientColors.map((col, idx) => {
                const offset =
                  resolvedGradientColors.length === 1
                    ? '0%'
                    : `${Math.round((idx / (resolvedGradientColors.length - 1)) * 100)}%`;
                return <Stop key={idx} offset={offset} stopColor={col} stopOpacity="1" />;
              })}
            </SvgLinearGradient>
          </Defs>
          <Rect
            x="0"
            y="0"
            width={width}
            height={height}
            rx={finalBorderRadius}
            ry={finalBorderRadius}
            fill={`url(#${gradientId})`}
          />
        </Svg>
      </View>
    );
  };

  // Determine circle vs pill vs standard container sizing
  const containerSizeStyle: ViewStyle = isCircle
    ? {
        width: resolvedCircleDimension,
        height: resolvedCircleDimension,
        borderRadius: finalBorderRadius,
        paddingHorizontal: 0,
        paddingVertical: 0,
      }
    : styles[`size_${normalizedSize}`];

  const hasOnlyIcon = Boolean(icon && !title && !children);
  const isCenterIcon = isCircle || hasOnlyIcon || iconPosition === 'center';

  return (
    <TouchableOpacity
      testID={testID}
      accessibilityRole="button"
      accessibilityState={{ disabled: !isInteractive, busy: isBusy }}
      onPress={handlePress}
      onLayout={handleLayout}
      disabled={disabled || isBusy}
      activeOpacity={0.7}
      style={[
        styles.base,
        dynamic.container,
        containerSizeStyle,
        style,
      ]}
    >
      {renderGradientBackground()}

      {isBusy ? (
        <ActivityIndicator
          testID={`${testID}-loading`}
          color={
            variant === 'outline' || variant === 'text' || variant === 'ghost'
              ? theme?.colors?.primary || '#E7252B'
              : '#FFFFFF'
          }
          size={normalizedSize === 'xs' || normalizedSize === 'sm' ? 'small' : 'small'}
        />
      ) : children ? (
        children
      ) : isCenterIcon ? (
        icon || (title ? (
          <Text
            style={[
              styles.textBase,
              dynamic.text,
              styles[`textSize_${normalizedSize}`],
              textStyle,
            ]}
          >
            {title}
          </Text>
        ) : null)
      ) : (
        <>
          {icon && iconPosition === 'left' && <View testID={`${testID}-icon-left`}>{icon}</View>}
          {title ? (
            <Text
              style={[
                styles.textBase,
                dynamic.text,
                styles[`textSize_${normalizedSize}`],
                textStyle,
              ]}
            >
              {title}
            </Text>
          ) : null}
          {icon && iconPosition === 'right' && <View testID={`${testID}-icon-right`}>{icon}</View>}
        </>
      )}
    </TouchableOpacity>
  );
};

const styles = StyleSheet.create({
  base: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'center',
    gap: 8,
    position: 'relative',
    overflow: 'hidden',
  },
  size_xs: {
    height: 28,
    paddingHorizontal: 8,
  },
  size_sm: {
    height: 36,
    paddingHorizontal: 12,
  },
  size_md: {
    height: 48,
    paddingHorizontal: 16,
  },
  size_lg: {
    height: 56,
    paddingHorizontal: 24,
  },
  textBase: {
    fontWeight: '600',
    textAlign: 'center',
  },
  textSize_xs: {
    fontSize: 11,
  },
  textSize_sm: {
    fontSize: 13,
  },
  textSize_md: {
    fontSize: 15,
  },
  textSize_lg: {
    fontSize: 16,
  },
});
