import React from 'react';
import { AppBottomSheet } from '../../modals/AppBottomSheet';
import {
  CalendarView,
  CalendarLocale,
  CalendarSelectionMode,
} from './CalendarView';

export type { CalendarLocale, CalendarSelectionMode };

export interface CalendarRangeBottomSheetProps {
  visible: boolean;
  onClose: () => void;
  onConfirm: (startDate: string, endDate: string, displayStr: string) => void;
  initialDisplayStr?: string;
  locale?: CalendarLocale;
  selectionMode?: CalendarSelectionMode;
  minDate?: string;
  maxDate?: string;
  testID?: string;
}

export const CalendarRangeBottomSheet: React.FC<CalendarRangeBottomSheetProps> = ({
  visible,
  onClose,
  onConfirm,
  locale,
  selectionMode = 'range',
  minDate,
  maxDate,
  testID = 'calendar-range-bottom-sheet',
}) => {
  return (
    <AppBottomSheet
      visible={visible}
      onClose={onClose}
      showHeader={false}
      testID={testID}
    >
      <CalendarView
        selectionMode={selectionMode}
        locale={locale}
        minDate={minDate}
        maxDate={maxDate}
        initialYear={2026}
        initialMonth={9}
        startDate="2026-10-15"
        endDate="2026-11-14"
        accentColor="#332940"
        onCancel={onClose}
        onConfirm={(start, end, displayStr) => {
          onConfirm(start, end, displayStr);
          onClose();
        }}
        testID={testID}
      />
    </AppBottomSheet>
  );
};
