import React from 'react';
import {
  View,
  Text,
  StyleSheet,
  TouchableOpacity,
  StyleProp,
  ViewStyle,
} from 'react-native';

export interface AuthStatCardProps {
  title: string;
  count: number | string;
  countColor: string;
  icon: React.ReactNode;
  iconBgColor?: string;
  onPress?: () => void;
  style?: StyleProp<ViewStyle>;
  testID?: string;
}

export const AuthStatCard: React.FC<AuthStatCardProps> = ({
  title,
  count,
  countColor,
  icon,
  iconBgColor = '#EBF4FF',
  onPress,
  style,
  testID = 'auth-stat-card',
}) => {
  const content = (
    <View style={[styles.card, style]} testID={testID}>
      <View style={styles.topRow}>
        <View style={[styles.iconBox, { backgroundColor: iconBgColor }]}>
          {icon}
        </View>
        <Text style={[styles.largeStatNumber, { color: countColor }]}>
          {count}
        </Text>
      </View>
      <Text style={styles.cardLabelText}>{title}</Text>
    </View>
  );

  if (onPress) {
    return (
      <TouchableOpacity
        style={styles.touchableWrapper}
        activeOpacity={0.85}
        onPress={onPress}
      >
        {content}
      </TouchableOpacity>
    );
  }

  return <View style={styles.touchableWrapper}>{content}</View>;
};

const styles = StyleSheet.create({
  touchableWrapper: {
    flex: 0.485,
  },
  card: {
    backgroundColor: '#FFFFFF',
    borderRadius: 14,
    padding: 16,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.05,
    shadowRadius: 6,
    elevation: 3,
  },
  topRow: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: 16,
  },
  iconBox: {
    width: 38,
    height: 38,
    borderRadius: 8,
    alignItems: 'center',
    justifyContent: 'center',
  },
  largeStatNumber: {
    fontSize: 26,
    fontWeight: '800',
  },
  cardLabelText: {
    fontSize: 13,
    color: '#374151',
    fontWeight: '600',
  },
});

