import React from 'react';
import {
  View,
  Text,
  StyleSheet,
  TouchableOpacity,
} from 'react-native';
import Svg, { Path, Rect, Circle } from 'react-native-svg';
import { SegmentedControl, SegmentItem } from '@mfe/ui-components/components/selection/SegmentedControl';
import { BottomSheetSelectField, SelectOption } from '@mfe/ui-components/components/selection/BottomSheetSelectField';
import { CalendarRangeBottomSheet } from '@mfe/ui-components/components/pickers/CalendarRangeBottomSheet';
import { PullToRefreshScrollView } from '@mfe/ui-components/components/scroll/PullToRefreshScrollView';
import { NoDataState } from '@mfe/ui-components/components/empty/NoDataState';
import { useApprovalViewModel, UseApprovalViewModelProps } from '../../viewmodels/useApprovalViewModel';
import { ApprovalStatus, ApprovalMenuType } from '../../models/ApprovalModel';

export interface ApprovalTabContentProps {
  onBackToDashboard?: () => void;
  onNavigateToDetail?: (approvalId: string) => void;
  viewModelProps?: UseApprovalViewModelProps;
}

const STATUS_SELECT_OPTIONS: SelectOption<ApprovalStatus | 'All'>[] = [
  { label: 'Requested', value: 'Requested' },
  { label: 'Approving', value: 'Approving' },
  { label: 'Approved', value: 'Approved' },
  { label: 'Rejected', value: 'Rejected' },
  { label: 'Returned', value: 'Returned' },
  { label: 'Resubmitted', value: 'Resubmitted' },
  { label: 'Request Amendment', value: 'Request Amendment' },
];

const MENU_SELECT_OPTIONS: SelectOption<ApprovalMenuType>[] = [
  { label: 'My Request', value: 'My Request' },
  { label: 'My Approval', value: 'My Approval' },
];

export const ApprovalTabContent: React.FC<ApprovalTabContentProps> = ({
  onBackToDashboard,
  onNavigateToDetail,
  viewModelProps,
}) => {
  const {
    tabType,
    setTabType,
    menuType,
    statusFilter,
    dateRangeStr,
    isInquiryOpen,
    setIsInquiryOpen,
    isDateModalVisible,
    setIsDateModalVisible,
    items,
    isLoading,
    handleSearch,
    handleClearDateRange,
    handleSelectMenuOption,
    handleSelectStatusOption,
    handleApplyDateRange,
  } = useApprovalViewModel(viewModelProps);

  const approvalSegments: SegmentItem<'loan' | 'general'>[] = [
    { label: 'Loan Approval', value: 'loan' },
    { label: 'General', value: 'general' },
  ];

  const handleCardPress = (id: string) => {
    if (onNavigateToDetail) {
      onNavigateToDetail(id);
    }
  };

  return (
    <View testID="approval-tab-content" style={styles.container}>
      {/* Top Header Bar */}
      <View style={styles.headerBar}>
        <TouchableOpacity
          testID="approval-back-button"
          style={styles.backBtn}
          activeOpacity={0.7}
          onPress={onBackToDashboard}
        >
          <Svg width={22} height={22} viewBox="0 0 24 24" fill="none">
            <Path d="M15 19L8 12L15 5" stroke="#1E293B" strokeWidth={2.4} strokeLinecap="round" strokeLinejoin="round" />
          </Svg>
        </TouchableOpacity>
        <Text style={styles.headerTitle}>Approval Request List</Text>
      </View>

      <PullToRefreshScrollView
        refreshing={isLoading}
        onRefresh={handleSearch}
        refreshTitle="Reloading approvals..."
        contentContainerStyle={styles.scrollContainer}
        testID="approval-list-pull-refresh"
      >
        {/* Inquiry Condition Accordion Header */}
        <TouchableOpacity
          testID="inquiry-condition-toggle"
          style={styles.inquiryBar}
          activeOpacity={0.7}
          onPress={() => setIsInquiryOpen(!isInquiryOpen)}
        >
          <Text style={styles.inquiryTitle}>Inquiry Condition</Text>
          <Svg width={20} height={20} viewBox="0 0 24 24" fill="none">
            <Path
              d={isInquiryOpen ? 'M18 15L12 9L6 15' : 'M6 9L12 15L18 9'}
              stroke="#1E293B"
              strokeWidth={2.2}
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </Svg>
        </TouchableOpacity>

        {/* Inquiry Condition Form Fields */}
        {isInquiryOpen && (
          <View style={styles.inquiryCard}>
            {/* Date Range Picker Trigger */}
            <TouchableOpacity
              testID="inquiry-date-range-field"
              style={styles.selectorField}
              activeOpacity={0.8}
              onPress={() => setIsDateModalVisible(true)}
            >
              <Text style={styles.selectorFieldText}>
                {dateRangeStr || 'Select date range'}
              </Text>
              <View style={styles.selectorRightIcons}>
                {!!dateRangeStr && (
                  <TouchableOpacity
                    testID="clear-date-range-btn"
                    activeOpacity={0.7}
                    onPress={handleClearDateRange}
                    style={{ padding: 4 }}
                  >
                    <Svg width={18} height={18} viewBox="0 0 24 24" fill="none">
                      <Circle cx="12" cy="12" r="10" fill="#64748B" />
                      <Path d="M15 9L9 15M9 9L15 15" stroke="#FFFFFF" strokeWidth={2} strokeLinecap="round" />
                    </Svg>
                  </TouchableOpacity>
                )}
                <Svg width={20} height={20} viewBox="0 0 24 24" fill="none">
                  <Rect x="3" y="4" width="18" height="18" rx="2" stroke="#1E293B" strokeWidth={2} />
                  <Path d="M16 2V6M8 2V6M3 10H21" stroke="#1E293B" strokeWidth={2} strokeLinecap="round" />
                </Svg>
              </View>
            </TouchableOpacity>

            {/* Reusable UI Component: BottomSheetSelectField for Status */}
            <BottomSheetSelectField<ApprovalStatus | 'All'>
              title="Select Menu"
              subtitle="Please select an option below:"
              options={STATUS_SELECT_OPTIONS}
              selectedValue={statusFilter}
              onSelect={(val) => handleSelectStatusOption(val)}
              placeholder="Search or select"
              testID="inquiry-status-select"
            />

            {/* Reusable UI Component: BottomSheetSelectField for Menu */}
            <BottomSheetSelectField<ApprovalMenuType>
              title="Select Menu"
              subtitle="Please select an option below:"
              options={MENU_SELECT_OPTIONS}
              selectedValue={menuType}
              onSelect={(val) => handleSelectMenuOption(val)}
              placeholder="Select Menu"
              testID="inquiry-menu-select"
            />

            {/* Search Button */}
            <TouchableOpacity
              testID="inquiry-search-button"
              style={styles.searchSubmitBtn}
              activeOpacity={0.85}
              onPress={handleSearch}
            >
              <Svg width={20} height={20} viewBox="0 0 24 24" fill="none">
                <Path
                  d="M21 21L16.65 16.65M19 11C19 15.4183 15.4183 19 11 19C6.58172 19 3 15.4183 3 11C3 6.58172 6.58172 3 11 3C15.4183 3 19 6.58172 19 11Z"
                  stroke="#FFFFFF"
                  strokeWidth={2.4}
                  strokeLinecap="round"
                />
              </Svg>
              <Text style={styles.searchSubmitText}>Search</Text>
            </TouchableOpacity>
          </View>
        )}

        {/* Reusable UI Component: SegmentedControl */}
        <SegmentedControl<'loan' | 'general'>
          items={approvalSegments}
          selectedValue={tabType}
          onSelect={setTabType}
          variant="filled"
          containerStyle={{ marginHorizontal: 16, marginTop: 16 }}
        />

        {/* Approval Request Cards / Empty State */}
        {items.length === 0 ? (
          <View style={styles.emptyContainer}>
            <NoDataState title="No data available." testID="approval-no-data" />
          </View>
        ) : (
          <View style={styles.cardListContainer}>
            {items.map((item) => (
              <TouchableOpacity
                key={item.id}
                testID={`approval-item-card-${item.applicationNo}`}
                style={styles.approvalCard}
                activeOpacity={0.85}
                onPress={() => handleCardPress(item.id)}
              >
                {/* Card Header: Application No and Status Badge */}
                <View style={styles.cardHeaderRow}>
                  <View style={styles.appNoGroup}>
                    <Svg width={20} height={20} viewBox="0 0 24 24" fill="none">
                      <Rect x="2" y="4" width="20" height="16" rx="2" stroke="#1E293B" strokeWidth={2} />
                      <Path d="M6 8H10M6 12H10M14 8H18M14 12H18M6 16H18" stroke="#1E293B" strokeWidth={1.8} strokeLinecap="round" />
                    </Svg>
                    <Text style={styles.appNoText}>{item.applicationNo}</Text>
                  </View>
                  <View
                    style={[
                      styles.statusPill,
                      item.status === 'Approved'
                        ? styles.statusApproved
                        : styles.statusRequested,
                    ]}
                  >
                    <Text style={styles.statusPillText}>{item.status}</Text>
                  </View>
                </View>

                {/* Key-Value Metrics */}
                <View style={styles.metricRow}>
                  <Text style={styles.metricLabel}>Customer No</Text>
                  <Text style={styles.metricValueBold}>{item.customerNo}</Text>
                </View>

                <View style={styles.metricRow}>
                  <Text style={styles.metricLabel}>Customer Name</Text>
                  <Text style={styles.metricValueBold}>{item.customerName}</Text>
                </View>

                <View style={styles.metricRow}>
                  <Text style={styles.metricLabel}>Request Date</Text>
                  <Text style={styles.metricValueBold}>{item.requestDate}</Text>
                </View>

                <View style={styles.metricRow}>
                  <Text style={styles.metricLabel}>Pending Duration</Text>
                  <Text style={styles.metricValueBold}>{item.pendingDuration}</Text>
                </View>

                {item.loanName ? (
                  <View style={styles.metricRow}>
                    <Text style={styles.metricLabel}>Loan Name</Text>
                    <Text style={styles.metricValueBold}>{item.loanName}</Text>
                  </View>
                ) : null}

                {item.loanAmount ? (
                  <View style={styles.metricRow}>
                    <Text style={styles.metricLabel}>Loan Amount</Text>
                    <Text style={styles.metricValueBold}>{item.loanAmount}</Text>
                  </View>
                ) : null}

                {item.loanTerm ? (
                  <View style={styles.metricRow}>
                    <Text style={styles.metricLabel}>Loan Term</Text>
                    <Text style={styles.metricValueBold}>{item.loanTerm}</Text>
                  </View>
                ) : null}
              </TouchableOpacity>
            ))}
          </View>
        )}

        <View style={{ height: 110 }} />
      </PullToRefreshScrollView>

      {/* Reusable UI Component: CalendarRangeBottomSheet */}
      <CalendarRangeBottomSheet
        visible={isDateModalVisible}
        onClose={() => setIsDateModalVisible(false)}
        onConfirm={(_s, _e, display) => handleApplyDateRange(display)}
        testID="approval-date-modal"
      />
    </View>
  );
};

