import React, { useState } from 'react';
import {
  View,
  Text,
  StyleSheet,
  ScrollView,
  TouchableOpacity,
  Linking,
  NativeSyntheticEvent,
  NativeScrollEvent,
} from 'react-native';
import Svg, { Path, Circle, Rect } from 'react-native-svg';
import { PullToRefreshScrollView } from '@mfe/ui-components/components/scroll/PullToRefreshScrollView';
import { FloatingActionButton } from '@mfe/ui-components/components/button/FloatingActionButton';
import { SegmentedControl, SegmentItem } from '@mfe/ui-components/components/selection/SegmentedControl';
import { AuthStatCard, HistoryStatusCard, DebtorMetricCard } from '../components';
import {
  useDashboardViewModel,
  UseDashboardViewModelProps,
} from '../../viewmodels/useDashboardViewModel';

export interface DashboardTabContentProps {
  userName?: string;
  onNavigateToShowcase?: () => void;
  onNavigateToNotifications?: () => void;
  onSelectApprovalTab?: () => void;
  onSelectDebtorTab?: () => void;
  onContentReady?: () => void;
  viewModelProps?: UseDashboardViewModelProps;
}

export const DashboardTabContent: React.FC<DashboardTabContentProps> = ({
  userName,
  onNavigateToShowcase,
  onNavigateToNotifications,
  onSelectApprovalTab,
  onSelectDebtorTab,
  onContentReady,
  viewModelProps,
}) => {
  const hasReportedReadyRef = React.useRef(false);
  const {
    activeSubTab,
    setActiveSubTab,
    summary,
    currentDebtorMetric,
    isRefreshing,
    handleRefresh,
  } = useDashboardViewModel(viewModelProps);

  const displayUserName = userName || summary.userName || 'Pang Phanna';

  const segmentItems: SegmentItem<'today' | 'week' | 'month'>[] = [
    { label: 'Today', value: 'today' },
    { label: 'This Week', value: 'week' },
    { label: 'This Month', value: 'month' },
  ];

  // Floating OTP animation state (expanded with label vs collapsed icon only)
  const [isOtpExtended, setIsOtpExtended] = useState(true);
  const lastOffsetY = React.useRef(0);

  const handleScroll = (event: NativeSyntheticEvent<NativeScrollEvent>) => {
    const currentOffsetY = event.nativeEvent.contentOffset.y;
    const diff = currentOffsetY - lastOffsetY.current;

    // Scrolling down (content moves up): collapse to icon only
    if (diff > 8 && isOtpExtended && currentOffsetY > 30) {
      setIsOtpExtended(false);
    }
    // Scrolling up (content moves down): extend with label
    else if (diff < -8 && !isOtpExtended) {
      setIsOtpExtended(true);
    }

    lastOffsetY.current = currentOffsetY;
  };

  const handleCall = (phoneNumber: string) => {
    Linking.openURL(`tel:${phoneNumber.replace(/[^0-9+]/g, '')}`);
  };

  return (
    <View style={styles.container}>
      {/* Dark Plum Header Bar */}
      <View style={styles.headerBar}>
        <View style={styles.profileSection}>
          <View style={styles.avatarCircle}>
            <Svg width={28} height={28} viewBox="0 0 24 24" fill="none">
              <Circle cx="12" cy="8" r="4" fill="#A0AEC0" />
              <Path
                d="M4 20C4 16.6863 7.58172 14 12 14C16.4183 14 20 16.6863 20 20"
                fill="#A0AEC0"
              />
            </Svg>
          </View>
          <View style={styles.greetingContainer}>
            {/* <Text style={styles.greetingSubtitle}>Hello React Native Base</Text> */}
            <Text style={styles.greetingSubtitle}>{summary.greeting || 'Hello React Native'}</Text>
            <Text style={styles.officerName}>{displayUserName}</Text>
          </View>
        </View>

        <View style={styles.headerActions}>
          <TouchableOpacity
            style={styles.headerIconBtn}
            activeOpacity={0.7}
            onPress={onNavigateToShowcase}
          >
            <Svg width={24} height={24} viewBox="0 0 24 24" fill="none">
              <Path d="M12 5V19M5 12H19" stroke="#FFFFFF" strokeWidth={2.2} strokeLinecap="round" />
            </Svg>
          </TouchableOpacity>
          <TouchableOpacity
            style={styles.headerIconBtn}
            activeOpacity={0.7}
            onPress={onNavigateToNotifications}
          >
            <Svg width={24} height={24} viewBox="0 0 24 24" fill="none">
              <Path
                d="M18 8A6 6 0 006 8C6 15 3 17 3 17H21S18 15 18 8Z"
                stroke="#FFFFFF"
                strokeWidth={2}
                strokeLinecap="round"
                strokeLinejoin="round"
              />
              <Path
                d="M13.73 21A2 2 0 0110.27 21"
                stroke="#FFFFFF"
                strokeWidth={2}
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            </Svg>
          </TouchableOpacity>
        </View>
      </View>

      <PullToRefreshScrollView
        refreshing={isRefreshing}
        onRefresh={handleRefresh}
        contentContainerStyle={styles.scrollContent}
        showsVerticalScrollIndicator={false}
        onScroll={handleScroll}
        scrollEventThrottle={16}
      >
        {/* SECTION 1: My To Authentication List (Reusable AuthStatCard component) */}
        <Text style={styles.sectionHeaderTitle}>My To Authentication List</Text>
        <View style={styles.cardRow}>
          {/* Need My Approval */}
          <AuthStatCard
            title="Need My Approval"
            count={summary.authStats.needMyApproval}
            countColor="#F59E0B"
            iconBgColor="#EBF4FF"
            onPress={onSelectApprovalTab}
            icon={
              <Svg width={22} height={22} viewBox="0 0 24 24" fill="none">
                <Rect x="3" y="4" width="18" height="17" rx="3" fill="#2B6CB0" />
                <Path d="M3 8H21" stroke="#FFFFFF" strokeWidth={1.5} />
                <Path d="M7 2V5M17 2V5" stroke="#2B6CB0" strokeWidth={2} strokeLinecap="round" />
                <Path d="M8 14L11 17L16 11" stroke="#FFFFFF" strokeWidth={2.2} strokeLinecap="round" strokeLinejoin="round" />
              </Svg>
            }
          />

          {/* My Approved */}
          <AuthStatCard
            title="My Approved"
            count={summary.authStats.myApproved}
            countColor="#10B981"
            iconBgColor="#E8F5E9"
            icon={
              <Svg width={22} height={22} viewBox="0 0 24 24" fill="none">
                <Rect x="4" y="4" width="16" height="16" rx="3" fill="#3B82F6" />
                <Path d="M8 12L11 15L16 9" stroke="#FFFFFF" strokeWidth={2.2} strokeLinecap="round" strokeLinejoin="round" />
              </Svg>
            }
          />
        </View>

        {/* SECTION 2: My To Do Authorization History (Reusable HistoryStatusCard component) */}
        <Text style={styles.sectionHeaderTitle}>My To Do Authorization History</Text>
        <View style={styles.historyGrid}>
          {/* Approved */}
          <HistoryStatusCard
            label="Approved"
            count={summary.todoHistory.approved}
            countColor="#10B981"
            icon={
              <Svg width={20} height={20} viewBox="0 0 24 24" fill="none">
                <Path d="M14 2H6C4.89543 2 4 2.89543 4 4V20C4 21.1046 4.89543 22 6 22H18C19.1046 22 20 21.1046 20 20V8L14 2Z" fill="#CBD5E1" />
                <Circle cx="10" cy="15" r="4" fill="#2C213F" />
                <Path d="M8.5 15L9.5 16L11.5 14" stroke="#FFFFFF" strokeWidth={1.5} strokeLinecap="round" />
              </Svg>
            }
          />

          {/* Waiting */}
          <HistoryStatusCard
            label="Waiting"
            count={summary.todoHistory.waiting}
            countColor="#3B82F6"
            icon={
              <Svg width={20} height={20} viewBox="0 0 24 24" fill="none">
                <Rect x="3" y="3" width="18" height="18" rx="3" fill="#E2E8F0" />
                <Path d="M7 16V13M12 16V10M17 16V8" stroke="#334135" strokeWidth={2.2} strokeLinecap="round" />
              </Svg>
            }
          />

          {/* Returned */}
          <HistoryStatusCard
            label="Returned"
            count={summary.todoHistory.returned}
            countColor="#F59E0B"
            icon={
              <Svg width={20} height={20} viewBox="0 0 24 24" fill="none">
                <Rect x="3" y="3" width="18" height="18" rx="3" fill="#E2E8F0" />
                <Path d="M15 15H9C7.89543 15 7 14.1046 7 13V13C7 11.8954 7.89543 11 9 11H17M11 9L7 13L11 17" stroke="#1E293B" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" />
              </Svg>
            }
          />

          {/* Rejected */}
          <HistoryStatusCard
            label="Rejected"
            count={summary.todoHistory.rejected}
            countColor="#EF4444"
            icon={
              <Svg width={20} height={20} viewBox="0 0 24 24" fill="none">
                <Rect x="3" y="3" width="18" height="18" rx="3" fill="#E2E8F0" />
                <Path d="M9 9L15 15M15 9L9 15" stroke="#1E293B" strokeWidth={2.5} strokeLinecap="round" />
              </Svg>
            }
          />
        </View>

        {/* SECTION 3: Segment Tab (Today, This Week, This Month) */}
        <SegmentedControl<'today' | 'week' | 'month'>
          items={segmentItems}
          selectedValue={activeSubTab}
          onSelect={setActiveSubTab}
          variant="filled"
          containerStyle={{ marginBottom: 16 }}
        />

        {/* SECTION 4: Goal of Debtor & Visited Debtor (Reusable DebtorMetricCard component) */}
        <View style={styles.debtorMetricsRow}>
          <DebtorMetricCard
            title="Goal of Debtor"
            count={currentDebtorMetric.goalOfDebtor}
            unit="People"
            onPress={onSelectDebtorTab}
            icon={
              <Svg width={28} height={28} viewBox="0 0 24 24" fill="none">
                <Circle cx="12" cy="8" r="5" fill="#2C213F" />
                <Path d="M3 20C3 16 7 14 12 14C17 14 21 16 21 20" fill="#2C213F" />
              </Svg>
            }
          />

          <DebtorMetricCard
            title="Visited Debtor"
            count={currentDebtorMetric.visitedDebtor}
            unit="People"
            onPress={onSelectDebtorTab}
            icon={
              <Svg width={28} height={28} viewBox="0 0 24 24" fill="none">
                <Circle cx="12" cy="7" r="4" fill="#2C213F" />
                <Path d="M5 21V19C5 15.5 8 13.5 12 13.5C16 13.5 19 15.5 19 19V21" fill="#2C213F" />
              </Svg>
            }
          />
        </View>

        {/* SECTION 5: Goal of Amount (Masked) */}
        <View style={styles.goalAmountCard}>
          <View style={styles.goalAmountHeaderRow}>
            <View style={styles.goalIconWrap}>
              <Svg width={22} height={22} viewBox="0 0 24 24" fill="none">
                <Rect x="2" y="5" width="20" height="14" rx="2" fill="#E2E8F0" />
                <Path d="M2 10H22" stroke="#64748B" strokeWidth={1.5} />
              </Svg>
            </View>
            <Text style={styles.goalAmountTitle}>Goal of Amount</Text>
          </View>
          <View style={styles.goalAmountValueRow}>
            <Text style={styles.maskedAsterisks}>{currentDebtorMetric.goalOfAmountMasked}</Text>
            <Text style={styles.currencyCode}>{currentDebtorMetric.currencyCode}</Text>
          </View>
        </View>

        {/* Extra Bottom Spacing for FAB and Navigation Bar */}
        <View
          style={{ height: 110 }}
          onLayout={() => {
            if (!hasReportedReadyRef.current && onContentReady) {
              hasReportedReadyRef.current = true;
              requestAnimationFrame(() => {
                requestAnimationFrame(() => {
                  onContentReady();
                });
              });
            }
          }}
        />
      </PullToRefreshScrollView>

      {/* Reusable Animated Floating Action Button */}
      <FloatingActionButton
        label="OTP"
        extended={isOtpExtended}
        collapsedSize={50}
        extendedWidth={96}
        backgroundColor="#FFFFFF"
        textColor="#2C213F"
        onPress={() => handleCall(summary.otpSupportPhone || '012 345 787')}
        icon={() => (
          <Svg width={22} height={22} viewBox="0 0 24 24" fill="none">
            <Rect x="5" y="3" width="14" height="18" rx="2" fill="#2C213F" />
            <Circle cx="12" cy="17" r="1.5" fill="#FFFFFF" />
            <Path d="M9 8H15M9 11H15" stroke="#FFFFFF" strokeWidth={1.5} strokeLinecap="round" />
          </Svg>
        )}
      />
    </View>
  );
};

