import React, { useState, useEffect, useRef } from 'react';
import {
  View,
  StyleSheet,
  StatusBar,
  BackHandler,
  TouchableOpacity,
} from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import Svg, { Path, Circle, Rect } from 'react-native-svg';
import { BottomNavigationBar, BottomTabItem } from '@mfe/ui-components/components/navigation/BottomNavigationBar';
import { useExitAppPrompt } from '@mfe/ui-components/hooks';
import {
  DashboardTabContent,
  ApprovalTabContent,
  DebtorTabContent,
  MenuTabContent,
} from './tabs';

export type DashboardBottomTab = 'dashboard' | 'approval' | 'debtor' | 'menu';

export interface DashboardScreenProps {
  onNavigateToShowcase?: () => void;
  onNavigateToNotification?: () => void;
  onNavigateToApprovalDetail?: (approvalId: string) => void;
  onLogout?: () => void;
  onFirstLayout?: () => void;
  userName?: string;
}

export const DashboardScreen: React.FC<DashboardScreenProps> = ({
  onNavigateToShowcase,
  onNavigateToNotification,
  onNavigateToApprovalDetail,
  onLogout,
  onFirstLayout,
  userName = 'Pang Phanna',
}) => {
  const insets = useSafeAreaInsets();
  const hasReportedLayoutRef = useRef(false);

  // Active bottom navigation tab
  const [activeTab, setActiveTab] = useState<DashboardBottomTab>('dashboard');

  // Prompt user to confirm exit when pressing back on the main dashboard tab
  useExitAppPrompt({
    enabled: activeTab === 'dashboard',
  });

  // Hardware back button behavior for sub-tabs
  useEffect(() => {
    if (activeTab === 'dashboard') return;

    const onBackPress = () => {
      // If on another bottom tab, return to dashboard first
      setActiveTab('dashboard');
      return true;
    };

    const sub = BackHandler.addEventListener('hardwareBackPress', onBackPress);
    return () => sub.remove();
  }, [activeTab]);

  // Bottom navigation items definition using standard BottomNavigationBar component
  const navTabs: BottomTabItem[] = [
    {
      key: 'dashboard',
      label: 'Dashboard',
      icon: (color) => (
        <Svg width={24} height={24} viewBox="0 0 24 24" fill="none">
          <Rect x="4" y="4" width="6" height="6" rx="1.5" fill={color} />
          <Rect x="14" y="4" width="6" height="6" rx="1.5" fill={color} />
          <Rect x="4" y="14" width="6" height="6" rx="1.5" fill={color} />
          <Rect x="14" y="14" width="6" height="6" rx="1.5" fill={color} />
        </Svg>
      ),
    },
    {
      key: 'approval',
      label: 'Approval',
      icon: (color) => (
        <Svg width={24} height={24} viewBox="0 0 24 24" fill="none">
          <Rect x="4" y="4" width="16" height="16" rx="4" fill={color} />
          <Path d="M8 12L11 15L16 9" stroke="#FFFFFF" strokeWidth={2.4} strokeLinecap="round" strokeLinejoin="round" />
        </Svg>
      ),
    },
    {
      key: 'camera-fab',
      customButton: (
        <View key="camera-fab" style={styles.fabSlot}>
          <TouchableOpacity
            style={styles.fabCenterButton}
            activeOpacity={0.85}
            onPress={() => {
              if (onNavigateToShowcase) onNavigateToShowcase();
            }}
          >
            <Svg width={26} height={26} viewBox="0 0 24 24" fill="none">
              <Path
                d="M23 19C23 19.5304 22.7893 20.0391 22.4142 20.4142C22.0391 20.7893 21.5304 21 21 21H3C2.46957 21 1.96086 20.7893 1.58579 20.4142C1.21071 20.0391 1 19.5304 1 19V8C1 7.46957 1.21071 6.96086 1.58579 6.58579C1.96086 6.21071 2.46957 6 3 6H7L9 3H15L17 6H21C21.5304 6 22.0391 6.21071 22.4142 6.58579C22.7893 6.96086 23 7.46957 23 8V19Z"
                stroke="#FFFFFF"
                strokeWidth={2.2}
                strokeLinecap="round"
                strokeLinejoin="round"
              />
              <Circle cx="12" cy="13" r="4" stroke="#FFFFFF" strokeWidth={2.2} />
            </Svg>
          </TouchableOpacity>
        </View>
      ),
    },
    {
      key: 'debtor',
      label: 'Debtor',
      icon: (color) => (
        <Svg width={24} height={24} viewBox="0 0 24 24" fill="none">
          <Circle cx="9" cy="8" r="3.5" fill={color} />
          <Path d="M2.5 18C2.5 15.5 5.5 14 9 14C12.5 14 15.5 15.5 15.5 18" stroke={color} strokeWidth={2.2} strokeLinecap="round" />
          <Circle cx="17.5" cy="9.5" r="2.5" fill={color} />
          <Path d="M16 17C16.8 15.8 18.2 15 20 15C21.2 15 22.2 15.5 22.8 16.2" stroke={color} strokeWidth={2} strokeLinecap="round" />
        </Svg>
      ),
    },
    {
      key: 'menu',
      label: 'Menu',
      icon: (color) => (
        <Svg width={24} height={24} viewBox="0 0 24 24" fill="none">
          <Rect x="4" y="5" width="4" height="4" rx="1" fill={color} />
          <Rect x="11" y="5" width="9" height="4" rx="1" fill={color} />
          <Rect x="4" y="11" width="4" height="4" rx="1" fill={color} />
          <Rect x="11" y="11" width="9" height="4" rx="1" fill={color} />
          <Rect x="4" y="17" width="4" height="4" rx="1" fill={color} />
          <Rect x="11" y="17" width="9" height="4" rx="1" fill={color} />
        </Svg>
      ),
    },
  ];

  return (
    <View style={styles.rootContainer}>
      <StatusBar
        translucent
        backgroundColor="transparent"
        barStyle={activeTab === 'dashboard' ? 'light-content' : 'dark-content'}
      />

      {/* Main View Area extending to the top screen edge with top insets padding */}
      <View
        style={[
          styles.contentArea,
          {
            paddingTop: insets.top,
            backgroundColor: activeTab === 'dashboard' ? '#2C213F' : '#FFFFFF',
          },
        ]}
      >
        {activeTab === 'dashboard' && (
          <DashboardTabContent
            userName={userName}
            onNavigateToShowcase={onNavigateToShowcase}
            onNavigateToNotifications={onNavigateToNotification}
            onSelectApprovalTab={() => setActiveTab('approval')}
            onSelectDebtorTab={() => setActiveTab('debtor')}
            onContentReady={() => {
              if (!hasReportedLayoutRef.current && onFirstLayout) {
                hasReportedLayoutRef.current = true;
                onFirstLayout();
              }
            }}
          />
        )}

        {activeTab === 'approval' && (
          <ApprovalTabContent
            onBackToDashboard={() => setActiveTab('dashboard')}
            onNavigateToDetail={onNavigateToApprovalDetail}
          />
        )}

        {activeTab === 'debtor' && (
          <DebtorTabContent onBackToDashboard={() => setActiveTab('dashboard')} />
        )}

        {activeTab === 'menu' && (
          <MenuTabContent
            onNavigateToShowcase={onNavigateToShowcase}
            onLogout={onLogout}
          />
        )}
      </View>

      {/* Persistent Bottom Navigation with Safe Area Bottom */}
      <BottomNavigationBar
        tabs={navTabs}
        activeTab={activeTab}
        onTabPress={(key) => {
          if (key !== 'camera-fab') {
            setActiveTab(key as DashboardBottomTab);
          }
        }}
        safeAreaBottom={insets.bottom}
        style={styles.navBar}
      />
    </View>
  );
};

const styles = StyleSheet.create({
  rootContainer: {
    flex: 1,
    backgroundColor: '#2C213F',
  },
  contentArea: {
    flex: 1,
  },
  navBar: {
    borderTopWidth: 1,
    borderTopColor: '#F1F5F9',
    backgroundColor: '#FFFFFF',
  },
  fabSlot: {
    flex: 1,
    alignItems: 'center',
    justifyContent: 'center',
    height: 48,
  },
  fabCenterButton: {
    position: 'absolute',
    top: -24,
    width: 58,
    height: 58,
    borderRadius: 29,
    backgroundColor: '#2C213F',
    alignItems: 'center',
    justifyContent: 'center',
    shadowColor: '#2C213F',
    shadowOffset: { width: 0, height: 6 },
    shadowOpacity: 0.35,
    shadowRadius: 8,
    elevation: 8,
  },
});
