import {
  defaultNetworkService,
  INetworkService,
  TR_CODES,
} from '@mfe/core';
import { ApprovalItemDTO, ApprovalFilterDTO } from '../models/ApprovalModel';

export interface IApprovalService {
  getApprovalList(filter?: ApprovalFilterDTO, useMock?: boolean): Promise<ApprovalItemDTO[]>;
  getApprovalDetail(id: string, useMock?: boolean): Promise<ApprovalItemDTO | null>;
  cancelModify(id: string, stepId: string, remark?: string, useMock?: boolean): Promise<boolean>;
}

export class ApprovalService implements IApprovalService {
  private static instance: ApprovalService;
  private networkService: INetworkService;
  private useMock: boolean;
  // Local state modifications applied on top of mock JSON responses during the session
  private stepOverrides: Map<string, { remark?: string; canCancelModify: boolean }> = new Map();

  constructor(
    networkService: INetworkService = defaultNetworkService,
    useMock: boolean = true
  ) {
    this.networkService = networkService;
    this.useMock = useMock;
  }

  public static getInstance(): ApprovalService {
    if (!ApprovalService.instance) {
      ApprovalService.instance = new ApprovalService();
    }
    return ApprovalService.instance;
  }

  public setUseMock(useMock: boolean): void {
    this.useMock = useMock;
  }

  public getUseMock(): boolean {
    return this.useMock;
  }

  private applyOverrides(items: ApprovalItemDTO[]): ApprovalItemDTO[] {
    return items.map((item) => {
      if (!item.approvalLine) return item;
      return {
        ...item,
        approvalLine: item.approvalLine.map((step) => {
          const key = `${item.id}:${step.id}`;
          const override = this.stepOverrides.get(key);
          if (!override) return step;
          return {
            ...step,
            remark: override.remark ?? step.remark,
            canCancelModify: override.canCancelModify,
          };
        }),
      };
    });
  }

  async getApprovalList(
    filter?: ApprovalFilterDTO,
    useMock: boolean = this.useMock
  ): Promise<ApprovalItemDTO[]> {
    const response = await this.networkService.request<{ items: ApprovalItemDTO[] } | ApprovalItemDTO[]>({
      trCode: TR_CODES.APPROVAL_LIST,
      payload: filter || {},
      useMock,
    });

    const rawItems = Array.isArray(response.body)
      ? response.body
      : response.body?.items || [];

    let result = this.applyOverrides(rawItems);

    if (filter) {
      if (filter.tabType) {
        result = result.filter((item) => item.tabType === filter.tabType);
      }
      if (filter.menuType) {
        result = result.filter((item) => item.menuType === filter.menuType);
      }
      if (filter.status) {
        result = result.filter((item) => item.status === filter.status);
      }
      if (filter.searchQuery && filter.searchQuery.trim()) {
        const query = filter.searchQuery.toLowerCase().trim();
        result = result.filter(
          (item) =>
            item.applicationNo.toLowerCase().includes(query) ||
            item.customerName.toLowerCase().includes(query) ||
            item.customerNo.toLowerCase().includes(query)
        );
      }
    }

    return result;
  }

  async getApprovalDetail(
    id: string,
    useMock: boolean = this.useMock
  ): Promise<ApprovalItemDTO | null> {
    const response = await this.networkService.request<{ items?: ApprovalItemDTO[]; item?: ApprovalItemDTO } | ApprovalItemDTO>({
      trCode: TR_CODES.APPROVAL_DETAIL,
      payload: { id },
      useMock,
    });

    if (!response.result || !response.body) {
      return null;
    }

    const bodyAny = response.body as any;
    if (bodyAny.id && bodyAny.applicationNo) {
      const [single] = this.applyOverrides([bodyAny as ApprovalItemDTO]);
      return single;
    }

    if (bodyAny.item) {
      const [single] = this.applyOverrides([bodyAny.item as ApprovalItemDTO]);
      return single;
    }

    const list: ApprovalItemDTO[] = Array.isArray(bodyAny)
      ? bodyAny
      : bodyAny.items || [];

    const applied = this.applyOverrides(list);
    const match = applied.find((a) => a.id === id || a.applicationNo === id);
    return match || null;
  }

  async cancelModify(
    id: string,
    stepId: string,
    remark?: string,
    useMock: boolean = this.useMock
  ): Promise<boolean> {
    const detail = await this.getApprovalDetail(id, useMock);
    if (!detail) return false;

    const response = await this.networkService.request<{ success: boolean }>({
      trCode: TR_CODES.APPROVAL_CANCEL_MODIFY,
      payload: { id: detail.id, applicationNo: detail.applicationNo, stepId, remark },
      useMock,
    });

    if (!response.result) {
      return false;
    }

    this.stepOverrides.set(`${detail.id}:${stepId}`, {
      remark,
      canCancelModify: false,
    });

    return true;
  }
}
